-- My Beautiful Property: first installation through Supabase SQL Editor.
-- Generated by npm run supabase:prepare-sql; edit the migration source instead.
-- Select the intended project, then run this ENTIRE file in one query.
-- Existing objects with the same names cause an error and roll back this run.
-- If already installed, inspect the existing schema instead of deleting tables.

begin;

-- My Beautiful Property: accounts, listings, public presentation, and inquiries.
-- Apply once to a new Supabase project using the SQL editor or `supabase db push`.
-- No service_role key is required by the application.

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  name text not null default '' check (char_length(name) <= 100),
  email text not null default '' check (char_length(email) <= 254),
  phone text not null default '' check (char_length(phone) <= 30),
  agency text not null default '' check (char_length(agency) <= 120),
  bio text not null default '' check (char_length(bio) <= 1000)
);

create table public.properties (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles(id) on delete cascade,
  slug text unique not null check (slug ~ '^[a-z0-9-]{1,110}$'),
  title text not null default '' check (char_length(title) <= 160),
  description text not null default '' check (char_length(description) <= 12000),
  location text not null default '' check (char_length(location) <= 200),
  price numeric not null default 0 check (price >= 0 and price <= 999999999999),
  currency text not null default 'USD' check (currency in ('USD', 'EUR', 'RON')),
  transaction text not null default 'sale' check (transaction in ('sale', 'rent')),
  type text not null default 'House' check (type in ('House', 'Condo', 'Penthouse', 'Land')),
  area numeric not null default 0 check (area >= 0 and area <= 999999999),
  area_unit text not null default 'sqft' check (area_unit in ('sqft', 'sqm')),
  bedrooms integer not null default 0 check (bedrooms between 0 and 100),
  bathrooms numeric not null default 0 check (bathrooms between 0 and 100 and bathrooms * 2 = trunc(bathrooms * 2)),
  amenities text[] not null default '{}' check (cardinality(amenities) <= 30),
  images text[] not null default '{}' check (cardinality(images) <= 20),
  template text not null default 'editorial' check (template in ('editorial', 'minimal', 'panorama')),
  status text not null default 'draft' check (status in ('draft', 'published')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint published_details_complete check (
    status = 'draft' or (
      char_length(trim(title)) >= 5 and char_length(trim(description)) >= 30
      and char_length(trim(location)) > 0 and price > 0 and area > 0
      and cardinality(images) > 0
    )
  )
);
create index properties_owner_created on public.properties(owner_id, created_at desc);

create table public.inquiries (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties(id) on delete cascade,
  owner_id uuid not null references public.profiles(id) on delete cascade,
  name text not null check (char_length(name) between 2 and 100),
  email text not null check (char_length(email) <= 254 and email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),
  phone text not null default '' check (char_length(phone) <= 30),
  message text not null check (char_length(message) between 10 and 2000),
  created_at timestamptz not null default now()
);
create index inquiries_owner_created on public.inquiries(owner_id, created_at desc);
create index inquiries_rate_limit on public.inquiries(property_id, email, created_at desc);

alter table public.profiles enable row level security;
alter table public.properties enable row level security;
alter table public.inquiries enable row level security;

revoke all on public.profiles, public.properties, public.inquiries from anon, authenticated;
grant select, update on public.profiles to authenticated;
grant select, insert, update, delete on public.properties to authenticated;
grant select, delete on public.inquiries to authenticated;

create policy "Agents can read their profile" on public.profiles for select to authenticated using (id = (select auth.uid()));
create policy "Agents can update their profile" on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy "Agents own their properties" on public.properties for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "Agents can read their inquiries" on public.inquiries for select to authenticated using (owner_id = (select auth.uid()));
create policy "Agents can remove their inquiries" on public.inquiries for delete to authenticated using (owner_id = (select auth.uid()));

create function public.create_agent_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles(id, name, email)
  values (new.id, left(coalesce(new.raw_user_meta_data ->> 'name', ''), 100), left(coalesce(new.email, ''), 254));
  return new;
end;
$$;
revoke all on function public.create_agent_profile() from public;
create trigger on_agent_signup after insert on auth.users for each row execute function public.create_agent_profile();

-- Also cover accounts created before applying this migration.
insert into public.profiles(id, name, email)
select id, left(coalesce(raw_user_meta_data ->> 'name', ''), 100), left(coalesce(email, ''), 254)
from auth.users on conflict (id) do nothing;

create function public.check_property_publication() returns trigger
language plpgsql security definer set search_path = '' as $$
declare agent public.profiles;
begin
  if tg_op = 'UPDATE' then
    if new.id <> old.id or new.owner_id <> old.owner_id or new.slug <> old.slug then
      raise exception 'Property identity, ownership, and public URL cannot be changed';
    end if;
    new.created_at = old.created_at;
  end if;
  new.updated_at = now();
  if new.status = 'published' then
    select * into agent from public.profiles where id = new.owner_id;
    if not found or char_length(trim(agent.name)) < 2
      or agent.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
      or char_length(regexp_replace(agent.phone, '[^0-9]', '', 'g')) < 8 then
      raise exception 'Complete your contact profile before publishing';
    end if;
  end if;
  if exists (select 1 from unnest(new.images) image where image is null or image !~ '^https://') then
    raise exception 'Property photos must use HTTPS storage URLs';
  end if;
  if exists (select 1 from unnest(new.amenities) amenity where amenity is null or char_length(amenity) > 60 or char_length(trim(amenity)) = 0) then
    raise exception 'Each amenity must contain 1 to 60 characters';
  end if;
  return new;
end;
$$;
revoke all on function public.check_property_publication() from public;
create trigger before_property_write before insert or update on public.properties for each row execute function public.check_property_publication();

create function public.check_agent_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.id <> old.id then raise exception 'Profile identity cannot be changed'; end if;
  if exists (select 1 from public.properties where owner_id = new.id and status = 'published') and (
    char_length(trim(new.name)) < 2 or new.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    or char_length(regexp_replace(new.phone, '[^0-9]', '', 'g')) < 8
  ) then raise exception 'Published websites require complete contact details'; end if;
  return new;
end;
$$;
revoke all on function public.check_agent_profile() from public;
create trigger before_agent_profile_update before update on public.profiles for each row execute function public.check_agent_profile();

-- Public visitors receive only a published listing and the current contact profile.
-- They have no direct SELECT grant on the private tables.
create function public.get_public_property(property_slug text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'property', to_jsonb(p) - array['owner_id', 'created_at', 'updated_at'],
    'profile', jsonb_build_object('name', a.name, 'email', a.email, 'phone', a.phone, 'agency', a.agency, 'bio', a.bio)
  )
  from public.properties p join public.profiles a on a.id = p.owner_id
  where p.slug = property_slug and p.status = 'published'
  limit 1;
$$;
revoke all on function public.get_public_property(text) from public;
grant execute on function public.get_public_property(text) to anon, authenticated;

-- Serialize requests for the same listing/email so simultaneous sends cannot
-- bypass the limit. Account ownership always comes from the published property.
create function public.submit_property_inquiry(property_slug text, sender_name text, sender_email text, sender_phone text, sender_message text) returns text
language plpgsql security definer set search_path = '' as $$
declare listing public.properties;
declare recent_count integer;
declare normalized_email text := lower(trim(sender_email));
begin
  if sender_name is null or sender_email is null or sender_phone is null or sender_message is null
    or char_length(trim(sender_name)) not between 2 and 100
    or char_length(normalized_email) > 254 or normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    or char_length(sender_phone) > 30 or char_length(trim(sender_message)) not between 10 and 2000 then
    return 'invalid';
  end if;
  select * into listing from public.properties where slug = property_slug and status = 'published' for share;
  if not found then return 'unavailable'; end if;
  perform pg_advisory_xact_lock(hashtextextended(listing.id::text || normalized_email, 0));
  select count(*) into recent_count from public.inquiries
    where property_id = listing.id and email = normalized_email and created_at > now() - interval '1 hour';
  if recent_count >= 3 then return 'rate_limited'; end if;
  insert into public.inquiries(property_id, owner_id, name, email, phone, message)
  values (listing.id, listing.owner_id, trim(sender_name), normalized_email, trim(sender_phone), trim(sender_message));
  return 'received';
end;
$$;
revoke all on function public.submit_property_inquiry(text, text, text, text, text) from public;
grant execute on function public.submit_property_inquiry(text, text, text, text, text) to anon, authenticated;

-- Marketing photos are public by URL, including photos attached to draft listings.
-- Do not upload private documents. Metadata and inquiries remain private.
insert into storage.buckets(id, name, public, file_size_limit, allowed_mime_types)
values ('property-images', 'property-images', true, 10485760, array['image/jpeg', 'image/png', 'image/webp']);

create policy "Agents upload their own marketing photos" on storage.objects
for insert to authenticated with check (bucket_id = 'property-images' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Agents read their own media metadata" on storage.objects
for select to authenticated using (bucket_id = 'property-images' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "Agents delete their own marketing photos" on storage.objects
for delete to authenticated using (bucket_id = 'property-images' and (storage.foldername(name))[1] = (select auth.uid())::text);


-- Additive update for existing installations. No API keys are stored here.
alter table public.properties add column if not exists website_copy jsonb
  check (website_copy is null or (
    jsonb_typeof(website_copy) = 'object' and octet_length(website_copy::text) <= 100000
  ));

-- Durable per-agent budget; callers cannot reset the counter directly.
create table if not exists public.property_story_usage (
  owner_id uuid primary key references public.profiles(id) on delete cascade,
  usage_day date not null,
  attempts integer not null check (attempts between 0 and 5),
  last_started_at timestamptz not null
);
alter table public.property_story_usage enable row level security;
revoke all on public.property_story_usage from public, anon, authenticated;

create or replace function public.reserve_property_story(property_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare agent_id uuid := auth.uid();
declare today date := (now() at time zone 'UTC')::date;
declare usage public.property_story_usage;
begin
  if agent_id is null or not exists (
    select 1 from public.properties p where p.id = property_id and p.owner_id = agent_id
  ) then return 'unavailable'; end if;
  perform pg_advisory_xact_lock(hashtextextended('property-story:' || agent_id::text, 0));
  select * into usage from public.property_story_usage where owner_id = agent_id;
  if found then
    if usage.last_started_at > now() - interval '1 minute'
      then return 'cooldown'; end if;
    if usage.usage_day = today and usage.attempts >= 5
      then return 'daily_limit'; end if;
  end if;
  insert into public.property_story_usage(owner_id, usage_day, attempts, last_started_at)
  values (agent_id, today, 1, now())
  on conflict (owner_id) do update set
    attempts = case when property_story_usage.usage_day = today then property_story_usage.attempts + 1 else 1 end,
    usage_day = today, last_started_at = now();
  return 'reserved';
end;
$$;
revoke all on function public.reserve_property_story(uuid) from public;
grant execute on function public.reserve_property_story(uuid) to authenticated;

notify pgrst, 'reload schema';


-- Add public agent portraits and retain leads when a property is deleted.
alter table public.profiles add column if not exists avatar_url text not null default ''
  check (char_length(avatar_url) <= 2048 and (avatar_url = '' or avatar_url ~ '^https://'));

alter table public.inquiries alter column property_id drop not null;
alter table public.inquiries drop constraint if exists inquiries_property_id_fkey;
alter table public.inquiries add constraint inquiries_property_id_fkey
  foreign key (property_id) references public.properties(id) on delete set null;

create or replace function public.delete_owned_property(property_id uuid) returns boolean
language sql security invoker set search_path = '' as $$
  with removed as (
    delete from public.properties p where p.id = property_id and p.owner_id = auth.uid() returning p.id
  ) select exists(select 1 from removed);
$$;
revoke all on function public.delete_owned_property(uuid) from public;
grant execute on function public.delete_owned_property(uuid) to authenticated;

create or replace function public.get_public_property(property_slug text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'property', to_jsonb(p) - array['owner_id', 'created_at', 'updated_at'],
    'profile', jsonb_build_object('name', a.name, 'email', a.email, 'phone', a.phone, 'agency', a.agency, 'bio', a.bio, 'avatar_url', a.avatar_url)
  )
  from public.properties p join public.profiles a on a.id = p.owner_id
  where p.slug = property_slug and p.status = 'published'
  limit 1;
$$;

insert into storage.buckets(id, name, public, file_size_limit, allowed_mime_types)
values ('agent-avatars', 'agent-avatars', true, 10485760, array['image/jpeg','image/png','image/webp'])
on conflict (id) do nothing;

drop policy if exists "Agents upload their own avatar" on storage.objects;
create policy "Agents upload their own avatar" on storage.objects for insert to authenticated
with check (bucket_id = 'agent-avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists "Agents read their own avatar metadata" on storage.objects;
create policy "Agents read their own avatar metadata" on storage.objects for select to authenticated
using (bucket_id = 'agent-avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists "Agents delete their own avatar" on storage.objects;
create policy "Agents delete their own avatar" on storage.objects for delete to authenticated
using (bucket_id = 'agent-avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
notify pgrst, 'reload schema';


-- Stripe sandbox only. These orders NEVER grant publication or video access.
create table if not exists public.stripe_test_orders (
  id uuid primary key default gen_random_uuid(),
  property_id uuid unique references public.properties(id) on delete set null,
  owner_id uuid references public.profiles(id) on delete set null,
  amount integer not null default 9700 check (amount = 9700),
  currency text not null default 'usd' check (currency = 'usd'),
  status text not null default 'pending' check (status in ('pending', 'paid')),
  attempt integer not null default 1,
  expires_at timestamptz not null default now() + interval '1 hour',
  stripe_session_id text unique,
  checkout_session_id text unique,
  paid_at timestamptz,
  created_at timestamptz not null default now()
);
alter table public.stripe_test_orders enable row level security;
revoke all on public.stripe_test_orders from public, anon, authenticated;
grant select, insert, update on public.stripe_test_orders to service_role;

-- A stable order/attempt gives Stripe the same idempotency key across tabs,
-- network retries and server restarts. An unpaid expired attempt can be retried.
create or replace function public.reserve_stripe_test_order(listing_id uuid, agent_id uuid)
returns public.stripe_test_orders
language plpgsql security definer set search_path = '' as $$
declare result public.stripe_test_orders;
begin
  perform pg_advisory_xact_lock(hashtextextended('stripe-test:' || listing_id::text, 0));
  if not exists (select 1 from public.properties where id = listing_id and owner_id = agent_id) then
    raise exception 'Property not available';
  end if;
  insert into public.stripe_test_orders(property_id, owner_id) values (listing_id, agent_id)
  on conflict (property_id) do nothing;
  select * into result from public.stripe_test_orders where property_id = listing_id for update;
  if result.status = 'pending' and result.expires_at < now() then
    update public.stripe_test_orders set attempt = attempt + 1, expires_at = now() + interval '1 hour'
    where id = result.id returning * into result;
  end if;
  return result;
end;
$$;
revoke all on function public.reserve_stripe_test_order(uuid, uuid) from public, anon, authenticated;
grant execute on function public.reserve_stripe_test_order(uuid, uuid) to service_role;
notify pgrst, 'reload schema';


-- Add live billing alongside the separate sandbox ledger. No charges are made.
create table if not exists public.property_billing_settings (
  singleton boolean primary key default true check (singleton),
  enabled boolean not null default false,
  activated_at timestamptz
);
insert into public.property_billing_settings(singleton) values (true) on conflict do nothing;
create table if not exists public.property_orders (
  id uuid primary key default gen_random_uuid(),
  property_id uuid unique references public.properties(id) on delete set null,
  owner_id uuid references public.profiles(id) on delete set null,
  amount integer not null default 9700 check (amount = 9700),
  currency text not null default 'usd' check (currency = 'usd'),
  status text not null default 'pending' check (status in ('pending','paid','refunded','disputed')),
  attempt integer not null default 1,
  expires_at timestamptz not null default now() + interval '1 hour',
  checkout_session_id text unique,
  payment_intent_id text unique,
  paid_at timestamptz,
  last_event_created bigint not null default 0,
  video_status text not null default 'not_ordered' check (video_status in ('not_ordered','pending','delivered','cancelled')),
  created_at timestamptz not null default now()
);
create table if not exists public.property_legacy_access (
  property_id uuid primary key references public.properties(id) on delete cascade,
  owner_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.property_billing_settings enable row level security;
alter table public.property_orders enable row level security;
alter table public.property_legacy_access enable row level security;
revoke all on public.property_billing_settings, public.property_orders, public.property_legacy_access from public, anon, authenticated;
grant select on public.property_billing_settings, public.property_legacy_access to service_role;
grant select, insert, update on public.property_orders to service_role;

-- Called only by the live server configuration. The switch persists in the DB:
-- switching Vercel back to test/off cannot silently remove the publication gate.
create or replace function public.activate_property_billing() returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  perform 1 from public.property_billing_settings where singleton for update;
  if (select enabled from public.property_billing_settings where singleton) then return true; end if;
  lock table public.properties in share row exclusive mode;
  insert into public.property_legacy_access(property_id,owner_id)
    select id,owner_id from public.properties where status='published' on conflict do nothing;
  update public.property_billing_settings set enabled=true,activated_at=now() where singleton;
  return true;
end;
$$;
revoke all on function public.activate_property_billing() from public, anon, authenticated;
grant execute on function public.activate_property_billing() to service_role;

create or replace function public.property_has_live_access(listing_id uuid,agent_id uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from public.property_legacy_access where property_id=listing_id and owner_id=agent_id)
    or exists(select 1 from public.property_orders where property_id=listing_id and owner_id=agent_id and status='paid');
$$;
revoke all on function public.property_has_live_access(uuid,uuid) from public, anon, authenticated;
grant execute on function public.property_has_live_access(uuid,uuid) to service_role;

create or replace function public.require_property_payment() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status='published' and coalesce((select enabled from public.property_billing_settings where singleton),false) then
    if exists(select 1 from public.property_legacy_access where property_id=new.id and owner_id=new.owner_id) then return new; end if;
    -- Serialize publication against concurrent refunds. A plain MVCC read can
    -- observe the old paid state while another transaction revokes the order.
    perform 1 from public.property_orders where property_id=new.id and owner_id=new.owner_id and status='paid' for share;
    if not found then
      raise exception 'PAYMENT_REQUIRED: Complete the $97 property purchase before publishing' using errcode='P0402';
    end if;
  end if;
  return new;
end;
$$;
revoke all on function public.require_property_payment() from public, anon, authenticated;
drop trigger if exists before_property_payment on public.properties;
create trigger before_property_payment before insert or update on public.properties for each row execute function public.require_property_payment();

create or replace function public.reserve_property_order(listing_id uuid,agent_id uuid) returns public.property_orders
language plpgsql security definer set search_path = '' as $$
declare result public.property_orders;
begin
  perform pg_advisory_xact_lock(hashtextextended('stripe-live:' || listing_id::text,0));
  if not exists(select 1 from public.properties where id=listing_id and owner_id=agent_id) then raise exception 'Property not available'; end if;
  insert into public.property_orders(property_id,owner_id) values(listing_id,agent_id) on conflict(property_id) do nothing;
  select * into result from public.property_orders where property_id=listing_id for update;
  if result.status='pending' and result.expires_at < now() then
    update public.property_orders set attempt=attempt+1,expires_at=now()+interval '1 hour' where id=result.id returning * into result;
  end if;
  return result;
end;
$$;
revoke all on function public.reserve_property_order(uuid,uuid) from public, anon, authenticated;
grant execute on function public.reserve_property_order(uuid,uuid) to service_role;

-- Atomic, idempotent fulfilment/revocation. Event order prevents an old paid
-- notification from restoring access after a refund/dispute. Full refunds are
-- terminal. A won dispute restores purchase access, but never republishes a page.
create or replace function public.apply_property_payment(order_id uuid,intent_id text,new_status text,event_created bigint) returns text
language plpgsql security definer set search_path = '' as $$
declare purchase public.property_orders;
begin
  select * into purchase from public.property_orders where id=order_id;
  if not found then raise exception 'Order not found'; end if;
  -- Use the same property -> order lock order as a publication update.
  if purchase.property_id is not null then perform 1 from public.properties where id=purchase.property_id for update; end if;
  select * into purchase from public.property_orders where id=order_id for update;
  if new_status not in ('paid','refunded','disputed') or intent_id !~ '^pi_' then raise exception 'Invalid payment'; end if;
  if purchase.payment_intent_id is not null and purchase.payment_intent_id<>intent_id then raise exception 'Payment identity mismatch'; end if;
  if (event_created<purchase.last_event_created and new_status<>'refunded') or purchase.status='refunded' then return purchase.status; end if;
  if event_created=purchase.last_event_created and purchase.status='disputed' and new_status='paid' then return purchase.status; end if;
  update public.property_orders set status=new_status,payment_intent_id=intent_id,
    paid_at=case when new_status='paid' then coalesce(paid_at,now()) else paid_at end,
    last_event_created=greatest(event_created,last_event_created),
    video_status=case when new_status<>'paid' then 'cancelled' when video_status='delivered' then 'delivered' else 'pending' end
    where id=order_id;
  if new_status<>'paid' and purchase.property_id is not null then
    update public.properties set status='draft' where id=purchase.property_id and owner_id=purchase.owner_id;
  end if;
  return new_status;
end;
$$;
revoke all on function public.apply_property_payment(uuid,text,text,bigint) from public, anon, authenticated;
grant execute on function public.apply_property_payment(uuid,text,text,bigint) to service_role;
notify pgrst, 'reload schema';


-- Publication intent, automatic paid publication, and one durable video job per purchase.
alter table public.property_orders add column if not exists publication_requested_at timestamptz;
alter table public.property_orders add column if not exists publication_completed_at timestamptz;
alter table public.property_orders add column if not exists publication_error text;
create table if not exists public.property_video_jobs (
  order_id uuid primary key references public.property_orders(id) on delete cascade,
  property_id uuid unique not null references public.properties(id) on delete cascade,
  owner_id uuid not null references public.profiles(id) on delete cascade,
  status text not null default 'queued' check(status in ('queued','processing','completed','failed','cancelled')),
  source jsonb not null,
  video_url text check(video_url is null or video_url ~ '^https://'),
  poster_url text check(poster_url is null or poster_url ~ '^https://'),
  attempts integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.property_video_jobs enable row level security;
revoke all on public.property_video_jobs from public,anon,authenticated;
grant select,insert,update,delete on public.property_video_jobs to service_role;

create or replace function public.finish_property_publication(purchase_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
declare listing public.properties;
begin
  select * into purchase from public.property_orders where id=purchase_id;
  if not found or purchase.property_id is null then return false; end if;
  select * into listing from public.properties where id=purchase.property_id and owner_id=purchase.owner_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where id=purchase_id for update;
  if purchase.status<>'paid' or purchase.publication_requested_at is null then return false; end if;
  if purchase.publication_completed_at is not null then return listing.status='published'; end if;
  begin
    update public.properties set status='published' where id=listing.id;
  exception when check_violation or raise_exception then
    update public.property_orders set publication_error='Your payment is confirmed. Review your property and contact details, then publish again at no extra charge.' where id=purchase_id;
    return false;
  end;
  insert into public.property_video_jobs(order_id,property_id,owner_id,source)
    values(purchase.id,listing.id,listing.owner_id,to_jsonb(listing)-array['owner_id','created_at','updated_at'])
    on conflict(order_id) do update set
      status=case when public.property_video_jobs.status='cancelled' then case when public.property_video_jobs.video_url is null then 'queued' else 'completed' end else public.property_video_jobs.status end,
      updated_at=now();
  update public.property_orders set publication_completed_at=now(),publication_error=null where id=purchase_id;
  return true;
end;
$$;
revoke all on function public.finish_property_publication(uuid) from public,anon,authenticated;
grant execute on function public.finish_property_publication(uuid) to service_role;

create or replace function public.on_property_payment_fulfilment() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.status='paid' and old.status='pending' and new.publication_requested_at is not null then
    perform public.finish_property_publication(new.id);
  elsif new.status in ('refunded','disputed') and old.status is distinct from new.status then
    update public.property_video_jobs set status='cancelled',updated_at=now() where order_id=new.id;
  end if;
  return new;
end;
$$;
revoke all on function public.on_property_payment_fulfilment() from public,anon,authenticated;
drop trigger if exists after_property_payment_fulfilment on public.property_orders;
create trigger after_property_payment_fulfilment after update of status on public.property_orders for each row execute function public.on_property_payment_fulfilment();

create or replace function public.request_property_publication(listing_id uuid,agent_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
declare done boolean;
begin
  perform 1 from public.properties where id=listing_id and owner_id=agent_id for update;
  if not found then raise exception 'Property not available'; end if;
  if exists(select 1 from public.property_legacy_access where property_id=listing_id and owner_id=agent_id) then
    update public.properties set status='published' where id=listing_id;
    return jsonb_build_object('published',true,'legacy',true);
  end if;
  purchase:=public.reserve_property_order(listing_id,agent_id);
  if purchase.status in ('refunded','disputed') then raise exception 'Contact support about this payment before publishing'; end if;
  update public.property_orders set publication_requested_at=now(),publication_completed_at=null,publication_error=null where id=purchase.id returning * into purchase;
  if purchase.status='paid' then
    done:=public.finish_property_publication(purchase.id);
    select * into purchase from public.property_orders where id=purchase.id;
    return jsonb_build_object('published',done,'paid',true,'publicationError',purchase.publication_error);
  end if;
  return jsonb_build_object('published',false,'order',to_jsonb(purchase));
end;
$$;
revoke all on function public.request_property_publication(uuid,uuid) from public,anon,authenticated;
grant execute on function public.request_property_publication(uuid,uuid) to service_role;

-- A retry requeues the existing failed job; it never creates another purchase.
create or replace function public.retry_property_video(listing_id uuid,agent_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
begin
  perform 1 from public.properties where id=listing_id and owner_id=agent_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where property_id=listing_id and owner_id=agent_id for update;
  if not found or purchase.status<>'paid' then return false; end if;
  update public.property_video_jobs set status='queued',updated_at=now()
    where order_id=purchase.id and owner_id=agent_id and status='failed';
  return found;
end;
$$;
revoke all on function public.retry_property_video(uuid,uuid) from public,anon,authenticated;
grant execute on function public.retry_property_video(uuid,uuid) to service_role;

-- Only completed video for an active paid purchase is included in public output.
create or replace function public.get_public_property(property_slug text) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'property',to_jsonb(p)-array['owner_id','created_at','updated_at'],
    'profile',jsonb_build_object('name',a.name,'email',a.email,'phone',a.phone,'agency',a.agency,'bio',a.bio,'avatar_url',a.avatar_url),
    'film',(select jsonb_build_object('src',v.video_url,'poster',coalesce(v.poster_url,p.images[1])) from public.property_video_jobs v join public.property_orders o on o.id=v.order_id where v.property_id=p.id and v.status='completed' and v.video_url is not null and o.status='paid')
  ) from public.properties p join public.profiles a on a.id=p.owner_id where p.slug=property_slug and p.status='published' limit 1;
$$;
revoke all on function public.get_public_property(text) from public;
