-- Platform roles are never read from editable profile fields or JWT user metadata.
create table if not exists public.platform_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  granted_at timestamptz not null default now()
);
create table if not exists public.property_admin_grants (
  order_id uuid primary key references public.property_orders(id) on delete cascade,
  property_id uuid unique not null references public.properties(id) on delete cascade,
  owner_id uuid not null references public.profiles(id) on delete cascade,
  granted_by uuid not null,
  reason text not null check(length(reason) between 1 and 500),
  granted_at timestamptz not null default now()
);
create table if not exists public.platform_admin_audit (
  id bigint generated always as identity primary key,
  actor_id uuid not null,
  property_id uuid not null,
  action text not null,
  details jsonb not null default '{}',
  created_at timestamptz not null default now()
);
alter table public.platform_admins enable row level security;
alter table public.property_admin_grants enable row level security;
alter table public.platform_admin_audit enable row level security;
revoke all on public.platform_admins,public.property_admin_grants,public.platform_admin_audit from public,anon,authenticated,service_role;
grant select on public.platform_admins,public.property_admin_grants,public.platform_admin_audit to service_role;
-- Explicit server read privileges; client RLS and grants remain unchanged.
grant select on public.profiles,public.properties to service_role;

create or replace function public.is_platform_admin() returns boolean
language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.platform_admins where user_id=auth.uid());
$$;
revoke all on function public.is_platform_admin() from public,anon;
grant execute on function public.is_platform_admin() to authenticated;

-- SQL Editor / database owner only. Neither the app nor an authenticated agent
-- can call this bootstrap function to promote an account.
create or replace function public.grant_platform_admin(account_email text) returns text
language plpgsql security definer set search_path='' as $$
declare target uuid; matches integer;
begin
  select count(*) into matches from auth.users where lower(email)=lower(btrim(account_email));
  if matches<>1 then raise exception 'Choose the exact login email of one existing account'; end if;
  select id into target from auth.users where lower(email)=lower(btrim(account_email));
  insert into public.platform_admins(user_id) values(target) on conflict do nothing;
  return 'MBP_ADMIN_GRANTED';
end;
$$;
revoke all on function public.grant_platform_admin(text) from public,anon,authenticated,service_role;

create or replace view public.platform_account_directory as
select p.id,p.name,p.email as contact_email,p.phone,p.agency,p.avatar_url,
  u.email as login_email,u.created_at,u.last_sign_in_at,
  (select count(*) from public.properties x where x.owner_id=p.id) as property_count
from public.profiles p join auth.users u on u.id=p.id;
revoke all on public.platform_account_directory from public,anon,authenticated;
grant select on public.platform_account_directory to service_role;

-- A complimentary grant is a separate entitlement, never a fake Stripe payment.
create or replace function public.property_order_fulfilled(purchase_id uuid) returns boolean
language sql volatile security definer set search_path='' as $$
  select exists(select 1 from public.property_orders o where o.id=purchase_id and
    (o.status='paid' or exists(select 1 from public.property_admin_grants g
      where g.order_id=o.id and g.property_id=o.property_id and g.owner_id=o.owner_id)));
$$;
revoke all on function public.property_order_fulfilled(uuid) from public,anon,authenticated;
grant execute on function public.property_order_fulfilled(uuid) to service_role;

create or replace function public.property_has_live_access(listing_id uuid,agent_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.property_legacy_access where property_id=listing_id and owner_id=agent_id)
    or exists(select 1 from public.property_orders where property_id=listing_id and owner_id=agent_id and public.property_order_fulfilled(id));
$$;
revoke all on function public.property_has_live_access(uuid,uuid) from public,anon,authenticated;
grant execute on function public.property_has_live_access(uuid,uuid) to service_role;

create or replace function public.require_property_payment() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.status='published' and coalesce((select enabled from public.property_billing_settings where singleton),false) then
    if exists(select 1 from public.property_legacy_access where property_id=new.id and owner_id=new.owner_id) then return new; end if;
    perform 1 from public.property_orders where property_id=new.id and owner_id=new.owner_id and public.property_order_fulfilled(id) for share;
    if not found then raise exception 'PAYMENT_REQUIRED: Complete the $97 property purchase before publishing' using errcode='P0402'; end if;
  end if;
  return new;
end;
$$;
revoke all on function public.require_property_payment() from public,anon,authenticated;

create or replace function public.admin_publish_property(listing_id uuid,actor_id uuid,grant_reason text,
  expected_session text default null,expected_attempt integer default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare listing public.properties; purchase public.property_orders; done boolean; is_free boolean;
begin
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  if grant_reason is null or length(btrim(grant_reason))<1 or length(grant_reason)>500 then raise exception 'Add a reason for this publication'; end if;
  select * into listing from public.properties where id=listing_id for update;
  if not found then raise exception 'Property not available'; end if;
  insert into public.property_orders(property_id,owner_id) values(listing.id,listing.owner_id) on conflict(property_id) do nothing;
  select * into purchase from public.property_orders where property_id=listing.id for update;
  -- The server expires an existing open Stripe session before this transaction.
  -- Fence in-flight session creation by rotating the attempt under the same lock.
  if purchase.checkout_session_id is distinct from expected_session or
    (expected_attempt is not null and purchase.attempt<>expected_attempt) then
    raise exception 'Checkout changed. Refresh this property and try again' using errcode='P0409';
  end if;
  is_free:=purchase.status<>'paid';
  if is_free then
    insert into public.property_admin_grants(order_id,property_id,owner_id,granted_by,reason)
      values(purchase.id,listing.id,listing.owner_id,actor_id,btrim(grant_reason)) on conflict(order_id) do nothing;
  end if;
  update public.property_orders set attempt=attempt+1,publication_requested_at=now(),publication_completed_at=null,
    publication_error=null,video_status=case when video_status='delivered' then 'delivered' else 'pending' end
    where id=purchase.id;
  done:=public.finish_property_publication(purchase.id);
  if not done then raise exception 'Complete the property and agent contact details before publishing'; end if;
  insert into public.platform_admin_audit(actor_id,property_id,action,details)
    values(actor_id,listing.id,'publish',jsonb_build_object('complimentary',is_free,'reason',btrim(grant_reason),'title',listing.title));
  return jsonb_build_object('published',true,'complimentary',is_free,'paid',purchase.status='paid','publicPath','/p/'||listing.slug);
end;
$$;
revoke all on function public.admin_publish_property(uuid,uuid,text,text,integer) from public,anon,authenticated;
grant execute on function public.admin_publish_property(uuid,uuid,text,text,integer) to service_role;


create or replace function public.claim_property_video(p_order uuid,p_lease uuid,p_model jsonb default null,p_input jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(purchase.id) or job.status not in ('queued','processing') or job.provider_phase='uncertain'
     or job.next_poll_at>now() or job.lease_until>now() then return null; end if;
  if job.status='queued' then
    if job.attempts>=3 or jsonb_typeof(p_model) is distinct from 'object' or jsonb_typeof(p_input) is distinct from 'object'
      or octet_length(p_model::text)>64000 or octet_length(p_input::text)>128000 then return null; end if;
    update public.property_video_jobs set status='processing',provider_phase='submitting',attempts=attempts+1,
      model_config=p_model,model_input=p_input,provider_request_id=null,last_error=null,
      lease_token=p_lease,lease_until=now()+interval '4 minutes',updated_at=now()
      where order_id=p_order returning * into job;
  else
    -- A crashed/timed-out submission may already have spent credits. Never resubmit it.
    if job.provider_request_id is null then
      update public.property_video_jobs set provider_phase='uncertain',lease_token=null,lease_until=null,
        last_error='Generation confirmation is delayed. Support must reconcile this request before another submission.',updated_at=now() where order_id=p_order;
      return null;
    end if;
    update public.property_video_jobs set lease_token=p_lease,lease_until=now()+interval '4 minutes',updated_at=now()
      where order_id=p_order returning * into job;
  end if;
  return to_jsonb(job);
end;
$$;


create or replace function public.bind_property_video_request(p_order uuid,p_attempt integer,p_request text)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs;
begin
  if p_request !~ '^[a-zA-Z0-9_-]{1,160}$' then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(purchase.id) or job.status<>'processing' or job.attempts<>p_attempt
      or (job.provider_request_id is not null and job.provider_request_id<>p_request) then return false; end if;
  update public.property_video_jobs set provider_request_id=p_request,provider_phase='submitted',last_error=null,next_poll_at=now(),updated_at=now() where order_id=p_order;
  return true;
end;
$$;


create or replace function public.advance_property_video(p_order uuid,p_lease uuid,p_attempt integer,p_phase text,p_url text default null,p_error text default null)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs;
begin
  if p_phase not in ('submitted','uncertain','failed','completed') then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(purchase.id) or job.status<>'processing' or job.lease_token is distinct from p_lease or job.attempts<>p_attempt then return false; end if;
  if p_phase='completed' and (job.provider_request_id is null or p_url is null or p_url !~ '^https://') then return false; end if;
  -- A callback may have recovered an ambiguous submission before this lease ends.
  if p_phase='uncertain' and job.provider_request_id is not null then p_phase:='submitted'; end if;
  update public.property_video_jobs set
    status=case when p_phase='completed' then 'completed' when p_phase='failed' then 'failed' else 'processing' end,
    provider_phase=p_phase,video_url=case when p_phase='completed' then p_url else video_url end,
    poster_url=case when p_phase='completed' then source->'images'->>0 else poster_url end,
    lease_token=null,lease_until=null,next_poll_at=now()+interval '30 seconds',last_error=left(p_error,500),updated_at=now()
    where order_id=p_order;
  if p_phase='completed' then update public.property_orders set video_status='delivered' where id=p_order; end if;
  return true;
end;
$$;


create or replace function public.retry_property_video(listing_id uuid,agent_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
begin
  perform 1 from public.properties where id=listing_id and owner_id=agent_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where property_id=listing_id and owner_id=agent_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then return false; end if;
  update public.property_video_jobs set status='queued',provider_phase='ready',provider_request_id=null,
    model_config=null,model_input=null,lease_token=null,lease_until=null,next_poll_at=now(),last_error=null,updated_at=now()
    where order_id=purchase.id and owner_id=agent_id and status='failed' and attempts<3
    and updated_at<now()-interval '1 minute';
  return found;
end;
$$;


create or replace function public.finish_property_publication(purchase_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
declare listing public.properties;
begin
  select * into purchase from public.property_orders where id=purchase_id;
  if not found or purchase.property_id is null then return false; end if;
  select * into listing from public.properties where id=purchase.property_id and owner_id=purchase.owner_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where id=purchase_id for update;
  if not public.property_order_fulfilled(purchase.id) or purchase.publication_requested_at is null then return false; end if;
  if purchase.publication_completed_at is not null then return listing.status='published'; end if;
  begin
    update public.properties set status='published' where id=listing.id;
  exception when check_violation or raise_exception then
    update public.property_orders set publication_error='Your payment is confirmed. Review your property and contact details, then publish again at no extra charge.' where id=purchase_id;
    return false;
  end;
  insert into public.property_video_jobs(order_id,property_id,owner_id,source)
    values(purchase.id,listing.id,listing.owner_id,to_jsonb(listing)-array['owner_id','created_at','updated_at'])
    on conflict(order_id) do update set
      status=case when public.property_video_jobs.status='cancelled' then
        case when public.property_video_jobs.video_url is not null then 'completed'
          when public.property_video_jobs.provider_phase='failed' then 'failed'
          when public.property_video_jobs.provider_request_id is not null or public.property_video_jobs.provider_phase in ('submitting','submitted','uncertain') or public.property_video_jobs.model_config->>'engine'='photo-montage-v1' then 'processing'
          else 'queued' end
        else public.property_video_jobs.status end,
      next_poll_at=now(),
      lease_token=case when public.property_video_jobs.status='cancelled' then null else public.property_video_jobs.lease_token end,
      lease_until=case when public.property_video_jobs.status='cancelled' then null else public.property_video_jobs.lease_until end,
      updated_at=now();
  update public.property_orders set publication_completed_at=now(),publication_error=null where id=purchase_id;
  return true;
end;
$$;


create or replace function public.claim_property_montage(p_order uuid,p_lease uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(purchase.id) or job.status not in ('queued','processing')
    or job.next_poll_at>now() or job.lease_until>now() or job.provider_request_id is not null then return null; end if;
  if job.status='queued' then
    if job.attempts>=3 then return null; end if;
    update public.property_video_jobs set status='processing',provider_phase='rendering',attempts=attempts+1,
      model_config='{"engine":"photo-montage-v1"}'::jsonb,model_input=null,montage_plan=null,montage_next_shot=0,montage_failures=0,
      last_error=null,lease_token=p_lease,lease_until=now()+interval '4 minutes',updated_at=now()
      where order_id=p_order returning * into job;
  else
    if job.model_config->>'engine' is distinct from 'photo-montage-v1' then return null; end if;
    update public.property_video_jobs set lease_token=p_lease,lease_until=now()+interval '4 minutes',updated_at=now()
      where order_id=p_order returning * into job;
  end if;
  return to_jsonb(job);
end;
$$;


create or replace function public.checkpoint_property_montage(p_order uuid,p_lease uuid,p_attempt integer,
  p_plan jsonb default null,p_next integer default null,p_url text default null,p_error text default null)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; shot_count integer;
begin
  if num_nonnulls(p_plan,p_next,p_url,p_error)<>1 then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(purchase.id) or job.status<>'processing' or job.lease_token is distinct from p_lease
    or job.attempts<>p_attempt or job.model_config->>'engine' is distinct from 'photo-montage-v1' then return false; end if;
  if p_error is not null then
    update public.property_video_jobs set montage_failures=montage_failures+1,
      status=case when montage_failures>=2 then 'failed' else 'processing' end,
      provider_phase=case when montage_failures>=2 then 'failed' else 'rendering' end,
      last_error=left(p_error,500),next_poll_at=now()+interval '5 minutes',lease_token=null,lease_until=null,updated_at=now()
      where order_id=p_order;
    return true;
  end if;
  if p_plan is not null then
    if job.montage_plan is not null or p_plan->>'engine' is distinct from 'photo-montage-v1'
      or jsonb_typeof(p_plan->'shots') is distinct from 'array' or octet_length(p_plan::text)>128000 then return false; end if;
    shot_count:=jsonb_array_length(p_plan->'shots');
    if shot_count<1 or shot_count>23 then return false; end if;
    update public.property_video_jobs set montage_plan=p_plan where order_id=p_order returning * into job;
  end if;
  shot_count:=jsonb_array_length(job.montage_plan->'shots');
  if p_next is not null then
    if shot_count is null or p_next<>job.montage_next_shot+1 or p_next>shot_count then return false; end if;
    update public.property_video_jobs set montage_next_shot=p_next where order_id=p_order returning * into job;
  end if;
  if p_url is not null then
    if shot_count is null or job.montage_next_shot<>shot_count or p_url !~ '^https://' then return false; end if;
    update public.property_video_jobs set status='completed',provider_phase='completed',video_url=p_url,
      poster_url=montage_plan->'shots'->0->>'image' where order_id=p_order;
    update public.property_orders set video_status='delivered' where id=p_order;
  end if;
  update public.property_video_jobs set montage_failures=0,last_error=null,lease_token=null,lease_until=null,
    next_poll_at=now()+interval '10 seconds',updated_at=now() where order_id=p_order;
  return true;
end;
$$;


create or replace function public.request_property_publication(listing_id uuid,agent_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
declare done boolean;
begin
  perform 1 from public.properties where id=listing_id and owner_id=agent_id for update;
  if not found then raise exception 'Property not available'; end if;
  if exists(select 1 from public.property_legacy_access where property_id=listing_id and owner_id=agent_id) then
    update public.properties set status='published' where id=listing_id;
    return jsonb_build_object('published',true,'legacy',true);
  end if;
  purchase:=public.reserve_property_order(listing_id,agent_id);
  if purchase.status in ('refunded','disputed') and not public.property_order_fulfilled(purchase.id) then raise exception 'Contact support about this payment before publishing'; end if;
  update public.property_orders set publication_requested_at=now(),publication_completed_at=null,publication_error=null where id=purchase.id returning * into purchase;
  if public.property_order_fulfilled(purchase.id) then
    done:=public.finish_property_publication(purchase.id);
    select * into purchase from public.property_orders where id=purchase.id;
    return jsonb_build_object('published',done,'paid',purchase.status='paid','complimentary',purchase.status<>'paid','publicationError',purchase.publication_error);
  end if;
  return jsonb_build_object('published',false,'order',to_jsonb(purchase));
end;
$$;


create or replace function public.get_public_property(property_slug text) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'property',to_jsonb(p)-array['owner_id','created_at','updated_at'],
    'profile',jsonb_build_object('name',a.name,'email',a.email,'phone',a.phone,'agency',a.agency,'bio',a.bio,'avatar_url',a.avatar_url),
    'film',(select jsonb_build_object('src',v.video_url,'poster',coalesce(v.poster_url,p.images[1])) from public.property_video_jobs v join public.property_orders o on o.id=v.order_id where v.property_id=p.id and v.status='completed' and v.video_url is not null and public.property_order_fulfilled(o.id))
  ) from public.properties p join public.profiles a on a.id=p.owner_id where p.slug=property_slug and p.status='published' limit 1;
$$;


create or replace function public.on_property_payment_fulfilment() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.status='paid' and old.status='pending' and new.publication_requested_at is not null then
    perform public.finish_property_publication(new.id);
  elsif new.status in ('refunded','disputed') and old.status is distinct from new.status and not public.property_order_fulfilled(new.id) then
    update public.property_video_jobs set status='cancelled',updated_at=now() where order_id=new.id;
  end if;
  return new;
end;
$$;


create or replace function public.apply_property_payment(order_id uuid,intent_id text,new_status text,event_created bigint) returns text
language plpgsql security definer set search_path = '' as $$
declare purchase public.property_orders;
begin
  select * into purchase from public.property_orders where id=order_id;
  if not found then raise exception 'Order not found'; end if;
  -- Use the same property -> order lock order as a publication update.
  if purchase.property_id is not null then perform 1 from public.properties where id=purchase.property_id for update; end if;
  select * into purchase from public.property_orders where id=order_id for update;
  if new_status not in ('paid','refunded','disputed') or intent_id !~ '^pi_' then raise exception 'Invalid payment'; end if;
  if purchase.payment_intent_id is not null and purchase.payment_intent_id<>intent_id then raise exception 'Payment identity mismatch'; end if;
  if (event_created<purchase.last_event_created and new_status<>'refunded') or purchase.status='refunded' then return purchase.status; end if;
  if event_created=purchase.last_event_created and purchase.status='disputed' and new_status='paid' then return purchase.status; end if;
  update public.property_orders set status=new_status,payment_intent_id=intent_id,
    paid_at=case when new_status='paid' then coalesce(paid_at,now()) else paid_at end,
    last_event_created=greatest(event_created,last_event_created),
    video_status=case when new_status<>'paid' and not exists(select 1 from public.property_admin_grants g where g.order_id=purchase.id) then 'cancelled' when video_status='delivered' then 'delivered' else 'pending' end
    where id=order_id;
  if new_status<>'paid' and purchase.property_id is not null and not public.property_order_fulfilled(purchase.id) then
    update public.properties set status='draft' where id=purchase.property_id and owner_id=purchase.owner_id;
  end if;
  return new_status;
end;
$$;

-- Align checkout reservation with publication/refund lock ordering.
create or replace function public.reserve_property_order(listing_id uuid,agent_id uuid) returns public.property_orders
language plpgsql security definer set search_path = '' as $$
declare result public.property_orders;
begin
  perform 1 from public.properties where id=listing_id and owner_id=agent_id for update;
  if not found then raise exception 'Property not available'; end if;
  perform pg_advisory_xact_lock(hashtextextended('stripe-live:' || listing_id::text,0));
  if not exists(select 1 from public.properties where id=listing_id and owner_id=agent_id) then raise exception 'Property not available'; end if;
  insert into public.property_orders(property_id,owner_id) values(listing_id,agent_id) on conflict(property_id) do nothing;
  select * into result from public.property_orders where property_id=listing_id for update;
  if result.status='pending' and result.expires_at < now() then
    update public.property_orders set attempt=attempt+1,expires_at=now()+interval '1 hour' where id=result.id returning * into result;
  end if;
  return result;
end;
$$;
notify pgrst,'reload schema';


-- Isolate regenerated intermediate files from stale workers. Existing in-flight
-- jobs retain their original paths; only new jobs/rebuilds receive a generation.
alter table public.property_video_jobs add column if not exists montage_generation uuid;
alter table public.property_video_jobs add column if not exists replacement_pending boolean not null default false;
alter table public.property_video_jobs alter column montage_generation set default gen_random_uuid();

create or replace function public.admin_rebuild_property_film(listing_id uuid,actor_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare listing public.properties; purchase public.property_orders; job public.property_video_jobs;
begin
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  select * into listing from public.properties where id=listing_id for update;
  if not found then raise exception 'Property not available'; end if;
  select * into purchase from public.property_orders where property_id=listing_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then
    raise exception 'Publish this property before rebuilding its film' using errcode='P0409';
  end if;
  select * into job from public.property_video_jobs where order_id=purchase.id for update;
  if not found or job.status not in ('completed','failed') or job.lease_until>now() then
    raise exception 'A film is already processing or is not ready to rebuild' using errcode='P0409';
  end if;
  if job.provider_request_id is not null or job.model_config->>'engine' is distinct from 'photo-montage-v1' then
    raise exception 'Only original-photo films can be rebuilt here' using errcode='P0409';
  end if;
  if coalesce(cardinality(listing.images),0)<1 then raise exception 'Add property photographs first'; end if;
  update public.property_video_jobs set
    status='queued',provider_phase='ready',attempts=0,replacement_pending=true,
    model_config='{"engine":"photo-montage-v1"}',model_input=null,
    source=to_jsonb(listing)-array['owner_id','created_at','updated_at'],
    montage_generation=gen_random_uuid(),montage_plan=null,montage_next_shot=0,montage_failures=0,
    lease_token=null,lease_until=null,next_poll_at=now(),last_error=null,updated_at=now()
    where order_id=purchase.id;
  -- Keep the previous public asset until checkpoint_property_montage atomically
  -- replaces it. No Stripe status, entitlement or publication changes here.
  update public.property_orders set video_status='pending' where id=purchase.id;
  insert into public.platform_admin_audit(actor_id,property_id,action,details)
    values(actor_id,listing_id,'rebuild_film',jsonb_build_object('previous_video',job.video_url,'renderer',2));
  return jsonb_build_object('videoStatus','queued','previousVideoRetained',job.video_url is not null);
end;
$$;
revoke all on function public.admin_rebuild_property_film(uuid,uuid) from public,anon,authenticated;
grant execute on function public.admin_rebuild_property_film(uuid,uuid) to service_role;

create or replace function public.get_public_property(property_slug text) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'property',to_jsonb(p)-array['owner_id','created_at','updated_at'],
    'profile',jsonb_build_object('name',a.name,'email',a.email,'phone',a.phone,'agency',a.agency,'bio',a.bio,'avatar_url',a.avatar_url),
    'film',(select jsonb_build_object('src',v.video_url,'poster',coalesce(v.poster_url,p.images[1])) from public.property_video_jobs v join public.property_orders o on o.id=v.order_id where v.property_id=p.id and v.video_url is not null and public.property_order_fulfilled(o.id))
  ) from public.properties p join public.profiles a on a.id=p.owner_id where p.slug=property_slug and p.status='published' limit 1;
$$;
notify pgrst,'reload schema';

create or replace function public.checkpoint_property_montage(p_order uuid,p_lease uuid,p_attempt integer,
  p_plan jsonb default null,p_next integer default null,p_url text default null,p_error text default null)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; shot_count integer;
begin
  if num_nonnulls(p_plan,p_next,p_url,p_error)<>1 then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(purchase.id) or job.status<>'processing' or job.lease_token is distinct from p_lease
    or job.attempts<>p_attempt or job.model_config->>'engine' is distinct from 'photo-montage-v1' then return false; end if;
  if p_error is not null then
    update public.property_video_jobs set montage_failures=montage_failures+1,
      status=case when montage_failures>=2 then 'failed' else 'processing' end,
      provider_phase=case when montage_failures>=2 then 'failed' else 'rendering' end,
      last_error=left(p_error,500),next_poll_at=now()+interval '5 minutes',lease_token=null,lease_until=null,updated_at=now()
      where order_id=p_order;
    return true;
  end if;
  if p_plan is not null then
    if job.montage_plan is not null or p_plan->>'engine' is distinct from 'photo-montage-v1'
      or jsonb_typeof(p_plan->'shots') is distinct from 'array' or octet_length(p_plan::text)>128000 then return false; end if;
    shot_count:=jsonb_array_length(p_plan->'shots');
    if shot_count<1 or shot_count>23 then return false; end if;
    update public.property_video_jobs set montage_plan=p_plan where order_id=p_order returning * into job;
  end if;
  shot_count:=jsonb_array_length(job.montage_plan->'shots');
  if p_next is not null then
    if shot_count is null or p_next<>job.montage_next_shot+1 or p_next>shot_count then return false; end if;
    update public.property_video_jobs set montage_next_shot=p_next where order_id=p_order returning * into job;
  end if;
  if p_url is not null then
    if shot_count is null or job.montage_next_shot<>shot_count or p_url !~ '^https://' then return false; end if;
    update public.property_video_jobs set status='completed',provider_phase='completed',video_url=p_url,replacement_pending=false,
      poster_url=montage_plan->'shots'->0->>'image' where order_id=p_order;
    update public.property_orders set video_status='delivered' where id=p_order;
  end if;
  update public.property_video_jobs set montage_failures=0,last_error=null,lease_token=null,lease_until=null,
    next_poll_at=now()+interval '10 seconds',updated_at=now() where order_id=p_order;
  return true;
end;
$$;



-- A retained previous video must not mark an in-progress replacement complete.
create or replace function public.finish_property_publication(purchase_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
declare listing public.properties;
begin
  select * into purchase from public.property_orders where id=purchase_id;
  if not found or purchase.property_id is null then return false; end if;
  select * into listing from public.properties where id=purchase.property_id and owner_id=purchase.owner_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where id=purchase_id for update;
  if not public.property_order_fulfilled(purchase.id) or purchase.publication_requested_at is null then return false; end if;
  if purchase.publication_completed_at is not null then return listing.status='published'; end if;
  begin
    update public.properties set status='published' where id=listing.id;
  exception when check_violation or raise_exception then
    update public.property_orders set publication_error='Your payment is confirmed. Review your property and contact details, then publish again at no extra charge.' where id=purchase_id;
    return false;
  end;
  insert into public.property_video_jobs(order_id,property_id,owner_id,source)
    values(purchase.id,listing.id,listing.owner_id,to_jsonb(listing)-array['owner_id','created_at','updated_at'])
    on conflict(order_id) do update set
      status=case when public.property_video_jobs.status='cancelled' then
        case when public.property_video_jobs.replacement_pending then
          case when public.property_video_jobs.provider_phase in ('failed','provider_failed') then 'failed'
            when (public.property_video_jobs.model_config->>'engine'='higgsfield-montage-v1' and public.property_video_jobs.model_config ? 'profile')
              or (public.property_video_jobs.model_config->>'engine'='photo-montage-v1' and public.property_video_jobs.attempts>0) then 'processing'
            else 'queued' end
          when public.property_video_jobs.video_url is not null then 'completed'
          when public.property_video_jobs.provider_phase in ('failed','provider_failed') then 'failed'
          when public.property_video_jobs.provider_request_id is not null or public.property_video_jobs.provider_phase in ('submitting','submitted','uncertain') or public.property_video_jobs.model_config->>'engine'='photo-montage-v1' or (public.property_video_jobs.model_config->>'engine'='higgsfield-montage-v1' and public.property_video_jobs.model_config ? 'profile') then 'processing'
          else 'queued' end
        else public.property_video_jobs.status end,
      next_poll_at=now(),
      lease_token=case when public.property_video_jobs.status='cancelled' then null else public.property_video_jobs.lease_token end,
      lease_until=case when public.property_video_jobs.status='cancelled' then null else public.property_video_jobs.lease_until end,
      updated_at=now();
  update public.property_orders set publication_completed_at=now(),publication_error=null where id=purchase_id;
  return true;
end;
$$;


-- Multi-photo provider films. A scene submission is durably reserved BEFORE
-- making a billable request; ambiguous submissions are never sent twice.
alter table public.property_video_jobs add column if not exists montage_edited_shots integer not null default 0;
create table if not exists public.property_film_scenes (
  order_id uuid not null references public.property_orders(id) on delete cascade,
  generation uuid not null,
  shot_index integer not null check(shot_index between 0 and 22),
  status text not null check(status in ('submitting','submitted','completed','uncertain','failed')),
  request_id text unique,
  model_config jsonb not null,
  model_input jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key(order_id,generation,shot_index)
);
alter table public.property_film_scenes enable row level security;
revoke all on public.property_film_scenes from public,anon,authenticated,service_role;
grant select on public.property_film_scenes to service_role;

create or replace function public.claim_property_ai_film(p_order uuid,p_lease uuid,p_model jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status not in ('queued','processing')
    or job.provider_phase='uncertain' or job.next_poll_at>now() or job.lease_until>now() then return null; end if;
  if job.status='queued' then
    if job.attempts>=3 or jsonb_typeof(p_model) is distinct from 'object' or octet_length(p_model::text)>64000 then return null; end if;
    update public.property_video_jobs set status='processing',provider_phase='planning',attempts=attempts+1,
      model_config=jsonb_build_object('engine','higgsfield-montage-v1','profile',p_model),model_input=null,provider_request_id=null,
      montage_generation=coalesce(montage_generation,gen_random_uuid()),montage_plan=null,montage_next_shot=0,montage_edited_shots=0,montage_failures=0,
      lease_token=p_lease,lease_until=now()+interval '4 minutes',last_error=null,updated_at=now()
      where order_id=p_order returning * into job;
  else
    if job.model_config->>'engine' is distinct from 'higgsfield-montage-v1' then return null; end if;
    update public.property_video_jobs set lease_token=p_lease,lease_until=now()+interval '4 minutes',updated_at=now()
      where order_id=p_order returning * into job;
  end if;
  return to_jsonb(job);
end;
$$;
revoke all on function public.claim_property_ai_film(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.claim_property_ai_film(uuid,uuid,jsonb) to service_role;

create or replace function public.reserve_property_film_scene(p_order uuid,p_lease uuid,p_attempt integer,p_input jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing' or job.lease_token is distinct from p_lease
    or job.attempts<>p_attempt or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1'
    or job.montage_plan is null or job.montage_next_shot>=jsonb_array_length(job.montage_plan->'shots') then return null; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=job.montage_generation and shot_index=job.montage_next_shot for update;
  if found then
    if scene.request_id is null then
      update public.property_film_scenes set status='uncertain',updated_at=now() where order_id=p_order and generation=scene.generation and shot_index=scene.shot_index;
      update public.property_video_jobs set provider_phase='uncertain',lease_token=null,lease_until=null,
        last_error='A scene submission needs reconciliation. No additional generation will be submitted automatically.',updated_at=now() where order_id=p_order;
      return null;
    end if;
    return to_jsonb(scene)||jsonb_build_object('submit',false);
  end if;
  if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>128000 then return null; end if;
  insert into public.property_film_scenes(order_id,generation,shot_index,status,model_config,model_input)
    values(p_order,job.montage_generation,job.montage_next_shot,'submitting',job.model_config->'profile',p_input) returning * into scene;
  update public.property_video_jobs set provider_phase='submitting',updated_at=now() where order_id=p_order;
  return to_jsonb(scene)||jsonb_build_object('submit',true);
end;
$$;
revoke all on function public.reserve_property_film_scene(uuid,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_property_film_scene(uuid,uuid,integer,jsonb) to service_role;

create or replace function public.bind_property_film_scene(p_order uuid,p_generation uuid,p_index integer,p_request text)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  if p_request !~ '^[a-zA-Z0-9_-]{1,160}$' then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing'
    or job.montage_generation is distinct from p_generation or job.montage_next_shot<>p_index
    or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1' then return false; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=p_generation and shot_index=p_index for update;
  if not found or scene.status not in ('submitting','submitted','uncertain') or (scene.request_id is not null and scene.request_id<>p_request) then return false; end if;
  update public.property_film_scenes set request_id=p_request,status='submitted',updated_at=now() where order_id=p_order and generation=p_generation and shot_index=p_index;
  update public.property_video_jobs set provider_phase='generating',last_error=null,next_poll_at=now(),updated_at=now() where order_id=p_order;
  return true;
end;
$$;
revoke all on function public.bind_property_film_scene(uuid,uuid,integer,text) from public,anon,authenticated;
grant execute on function public.bind_property_film_scene(uuid,uuid,integer,text) to service_role;

create or replace function public.checkpoint_property_ai_film(p_order uuid,p_lease uuid,p_attempt integer,
  p_plan jsonb default null,p_scene integer default null,p_edit integer default null,p_url text default null,
  p_error text default null,p_failure text default 'delayed')
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; total integer; known boolean;
begin
  if num_nonnulls(p_plan,p_scene,p_edit,p_url,p_error)>1 then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing' or job.lease_token is distinct from p_lease
    or job.attempts<>p_attempt or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1' then return false; end if;
  if p_error is not null then
    select exists(select 1 from public.property_film_scenes where order_id=p_order and generation=job.montage_generation and shot_index=job.montage_next_shot and request_id is not null) into known;
    if p_failure='uncertain' and not known then
      update public.property_film_scenes set status='uncertain',updated_at=now() where order_id=p_order and generation=job.montage_generation and shot_index=job.montage_next_shot;
    end if;
    update public.property_video_jobs set montage_failures=montage_failures+1,
      status=case when p_failure='failed' or (p_failure='delayed' and montage_failures>=2) then 'failed' else 'processing' end,
      provider_phase=case when p_failure='uncertain' and not known then 'uncertain' when p_failure='failed' then 'provider_failed' when p_failure='delayed' and montage_failures>=2 then 'failed' else 'generating' end,
      last_error=left(p_error,500),lease_token=null,lease_until=null,next_poll_at=now()+interval '2 minutes',updated_at=now() where order_id=p_order;
    return true;
  end if;
  if p_plan is not null then
    if job.montage_plan is not null or p_plan->>'engine' is distinct from 'higgsfield-montage-v1'
      or jsonb_typeof(p_plan->'shots') is distinct from 'array' or octet_length(p_plan::text)>128000 then return false; end if;
    total:=jsonb_array_length(p_plan->'shots');
    if total<1 or total>23 then return false; end if;
    update public.property_video_jobs set montage_plan=p_plan where order_id=p_order returning * into job;
  end if;
  total:=jsonb_array_length(job.montage_plan->'shots');
  if p_scene is not null then
    if total is null or p_scene<>job.montage_next_shot or p_scene>=total then return false; end if;
    update public.property_film_scenes set status='completed',updated_at=now()
      where order_id=p_order and generation=job.montage_generation and shot_index=p_scene and request_id is not null and status='submitted';
    if not found then return false; end if;
    update public.property_video_jobs set montage_next_shot=montage_next_shot+1 where order_id=p_order returning * into job;
  end if;
  if p_edit is not null then
    if total is null or job.montage_next_shot<>total or p_edit<>job.montage_edited_shots or p_edit>=total then return false; end if;
    update public.property_video_jobs set montage_edited_shots=montage_edited_shots+1 where order_id=p_order returning * into job;
  end if;
  if p_url is not null then
    if total is null or job.montage_next_shot<>total or job.montage_edited_shots<>total or p_url !~ '^https://' then return false; end if;
    update public.property_video_jobs set status='completed',provider_phase='completed',video_url=p_url,replacement_pending=false,
      poster_url=montage_plan->'shots'->0->>'image' where order_id=p_order;
    update public.property_orders set video_status='delivered' where id=p_order;
  end if;
  update public.property_video_jobs set montage_failures=0,last_error=null,lease_token=null,lease_until=null,
    next_poll_at=case when num_nonnulls(p_plan,p_scene,p_edit,p_url)>0 then now() else now()+interval '30 seconds' end,updated_at=now() where order_id=p_order;
  return true;
end;
$$;
revoke all on function public.checkpoint_property_ai_film(uuid,uuid,integer,jsonb,integer,integer,text,text,text) from public,anon,authenticated;
grant execute on function public.checkpoint_property_ai_film(uuid,uuid,integer,jsonb,integer,integer,text,text,text) to service_role;

create or replace function public.admin_rebuild_property_film(listing_id uuid,actor_id uuid,target_engine text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare listing public.properties; purchase public.property_orders; job public.property_video_jobs;
begin
  if target_engine not in ('photo-montage-v1','higgsfield-montage-v1') then raise exception 'Choose a supported film mode'; end if;
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  select * into listing from public.properties where id=listing_id for update;
  if not found then raise exception 'Property not available'; end if;
  select * into purchase from public.property_orders where property_id=listing_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then
    raise exception 'Publish this property before rebuilding its film' using errcode='P0409';
  end if;
  select * into job from public.property_video_jobs where order_id=purchase.id for update;
  if not found or job.status not in ('completed','failed') or job.lease_until>now() then
    raise exception 'A film is already processing or is not ready to rebuild' using errcode='P0409';
  end if;
  if job.provider_phase='uncertain' then raise exception 'Reconcile the existing generation before rebuilding' using errcode='P0409'; end if;
  if coalesce(cardinality(listing.images),0)<1 then raise exception 'Add property photographs first'; end if;
  update public.property_video_jobs set
    status='queued',provider_phase='ready',attempts=0,replacement_pending=true,
    model_config=jsonb_build_object('engine',target_engine),model_input=null,provider_request_id=null,
    source=to_jsonb(listing)-array['owner_id','created_at','updated_at'],
    montage_generation=gen_random_uuid(),montage_plan=null,montage_next_shot=0,montage_failures=0,montage_edited_shots=0,
    lease_token=null,lease_until=null,next_poll_at=now(),last_error=null,updated_at=now()
    where order_id=purchase.id;
  -- Keep the previous public asset until checkpoint_property_montage atomically
  -- replaces it. No Stripe status, entitlement or publication changes here.
  update public.property_orders set video_status='pending' where id=purchase.id;
  insert into public.platform_admin_audit(actor_id,property_id,action,details)
    values(actor_id,listing_id,'rebuild_film',jsonb_build_object('previous_video',job.video_url,'renderer',target_engine,'previous_provider_request',job.provider_request_id));
  return jsonb_build_object('videoStatus','queued','previousVideoRetained',job.video_url is not null);
end;
$$;
revoke all on function public.admin_rebuild_property_film(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.admin_rebuild_property_film(uuid,uuid,text) to service_role;


create or replace function public.retry_property_video(listing_id uuid,agent_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
begin
  perform 1 from public.properties where id=listing_id and owner_id=agent_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where property_id=listing_id and owner_id=agent_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then return false; end if;
  if exists(select 1 from public.property_video_jobs where order_id=purchase.id and model_config->>'engine'='higgsfield-montage-v1') then
    update public.property_video_jobs set status='processing',provider_phase='generating',attempts=attempts+1,
      lease_token=null,lease_until=null,next_poll_at=now(),last_error=null,montage_failures=0,updated_at=now()
      where order_id=purchase.id and status='failed' and provider_phase not in ('uncertain','provider_failed')
      and attempts<3 and updated_at<now()-interval '1 minute';
    return found;
  end if;
  update public.property_video_jobs set status='queued',provider_phase='ready',provider_request_id=null,
    model_config=null,model_input=null,lease_token=null,lease_until=null,next_poll_at=now(),last_error=null,updated_at=now()
    where order_id=purchase.id and owner_id=agent_id and status='failed' and attempts<3
    and updated_at<now()-interval '1 minute';
  return found;
end;
$$;



notify pgrst,'reload schema';

-- Preserve pinned provider requests and montage progress when a won dispute is republished.
create or replace function public.finish_property_publication(purchase_id uuid) returns boolean
language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders;
declare listing public.properties;
begin
  select * into purchase from public.property_orders where id=purchase_id;
  if not found or purchase.property_id is null then return false; end if;
  select * into listing from public.properties where id=purchase.property_id and owner_id=purchase.owner_id for update;
  if not found then return false; end if;
  select * into purchase from public.property_orders where id=purchase_id for update;
  if not public.property_order_fulfilled(purchase.id) or purchase.publication_requested_at is null then return false; end if;
  if purchase.publication_completed_at is not null then return listing.status='published'; end if;
  begin
    update public.properties set status='published' where id=listing.id;
  exception when check_violation or raise_exception then
    update public.property_orders set publication_error='Your payment is confirmed. Review your property and contact details, then publish again at no extra charge.' where id=purchase_id;
    return false;
  end;
  insert into public.property_video_jobs(order_id,property_id,owner_id,source)
    values(purchase.id,listing.id,listing.owner_id,to_jsonb(listing)-array['owner_id','created_at','updated_at'])
    on conflict(order_id) do update set
      status=case when public.property_video_jobs.status='cancelled' then
        case when public.property_video_jobs.replacement_pending then
          case when public.property_video_jobs.provider_phase in ('failed','provider_failed') then 'failed'
            when (public.property_video_jobs.model_config->>'engine'='higgsfield-montage-v1' and public.property_video_jobs.model_config ? 'profile')
              or (public.property_video_jobs.model_config->>'engine'='photo-montage-v1' and public.property_video_jobs.attempts>0) then 'processing'
            else 'queued' end
          when public.property_video_jobs.video_url is not null then 'completed'
          when public.property_video_jobs.provider_phase in ('failed','provider_failed') then 'failed'
          when public.property_video_jobs.provider_request_id is not null or public.property_video_jobs.provider_phase in ('submitting','submitted','uncertain') or public.property_video_jobs.model_config->>'engine'='photo-montage-v1' or (public.property_video_jobs.model_config->>'engine'='higgsfield-montage-v1' and public.property_video_jobs.model_config ? 'profile') then 'processing'
          else 'queued' end
        else public.property_video_jobs.status end,
      next_poll_at=now(),
      lease_token=case when public.property_video_jobs.status='cancelled' then null else public.property_video_jobs.lease_token end,
      lease_until=case when public.property_video_jobs.status='cancelled' then null else public.property_video_jobs.lease_until end,
      updated_at=now();
  update public.property_orders set publication_completed_at=now(),publication_error=null where id=purchase_id;
  return true;
end;
$$;



-- Late single-clip callbacks must never attach to a new multi-scene generation.
create or replace function public.bind_property_video_request(p_order uuid,p_attempt integer,p_request text)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs;
begin
  if p_request !~ '^[a-zA-Z0-9_-]{1,160}$' then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or job.model_config->>'engine' in ('photo-montage-v1','higgsfield-montage-v1') or not public.property_order_fulfilled(purchase.id) or job.status<>'processing' or job.attempts<>p_attempt
      or (job.provider_request_id is not null and job.provider_request_id<>p_request) then return false; end if;
  update public.property_video_jobs set provider_request_id=p_request,provider_phase='submitted',last_error=null,next_poll_at=now(),updated_at=now() where order_id=p_order;
  return true;
end;
$$;


-- Address-based public URLs. Existing property identifiers and shared URLs remain valid.
alter table public.properties add column if not exists address_slug text
  check (address_slug is null or address_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(address_slug) <= 110);
create unique index if not exists properties_address_slug_unique on public.properties(address_slug);

-- One namespace for current addresses, previous addresses and legacy links.
-- Private: resolving a URL still requires a published property through the RPC below.
create table if not exists public.property_url_slugs (
  slug text primary key check (slug ~ '^[a-z0-9-]{1,110}$'),
  property_id uuid not null references public.properties(id) on delete cascade deferrable initially deferred
);
create index if not exists property_url_slugs_property on public.property_url_slugs(property_id);
alter table public.property_url_slugs enable row level security;
revoke all on public.property_url_slugs from public,anon,authenticated;

-- Remove combining marks before punctuation conversion (portable PostgreSQL Unicode escapes).
create or replace function public.address_slug_base(address text) returns text
language sql immutable set search_path='' as $$
  select coalesce(nullif(trim(both '-' from left(regexp_replace(
    regexp_replace(lower(translate(normalize(coalesce(address,''), NFD), 'ŁłØøĐđÆæŒœß', 'LlOoDdAaOos')),
      U&'[\0300-\036f]', '', 'g'), '[^a-z0-9]+', '-', 'g'),90)),''),'property');
$$;
revoke all on function public.address_slug_base(text) from public,anon,authenticated;

create or replace function public.assign_property_address_url() returns trigger
language plpgsql security definer set search_path='' as $$
declare base text; candidate text; holder uuid; suffix integer:=1;
begin
  -- Serialize namespace allocation, including two agents publishing the same address.
  perform pg_advisory_xact_lock(hashtextextended('property-public-url-namespace',0));
  insert into public.property_url_slugs(slug,property_id) values(new.slug,new.id)
    on conflict(slug) do nothing;
  select property_id into holder from public.property_url_slugs where slug=new.slug;
  if holder is distinct from new.id then raise exception 'Property URL is already in use'; end if;

  -- This is a server-owned field: callers cannot choose or steal another public URL.
  if tg_op='INSERT' then new.address_slug:=null;
  else new.address_slug:=old.address_slug;
  end if;
  if new.status<>'published' then return new; end if;
  -- Ordinary edits do not change a published URL even if a shorter alias becomes free.
  if tg_op='UPDATE' and old.status='published' and old.address_slug is not null
    and new.location is not distinct from old.location then return new; end if;
  base:=public.address_slug_base(new.location);
  if base=any(array['admin','api','dashboard','login','reset-password','templates','preview','p','_next','favicon','robots','sitemap','icon','signup','register','auth','account','settings','pricing','contact','about','terms','privacy','support']) then
    base:=base||'-property';
  end if;
  candidate:=base;
  loop
    insert into public.property_url_slugs(slug,property_id) values(candidate,new.id)
      on conflict(slug) do nothing;
    select property_id into holder from public.property_url_slugs where slug=candidate;
    exit when holder=new.id;
    suffix:=suffix+1;
    candidate:=base||'-'||suffix::text;
  end loop;
  new.address_slug:=candidate;
  return new;
end;
$$;
revoke all on function public.assign_property_address_url() from public,anon,authenticated;

-- Reserve existing links first, then generate addresses for already-published websites.
insert into public.property_url_slugs(slug,property_id)
  select slug,id from public.properties on conflict(slug) do nothing;
drop trigger if exists zz_property_address_url on public.properties;
create trigger zz_property_address_url before insert or update on public.properties
  for each row execute function public.assign_property_address_url();
update public.properties set location=location where status='published' and address_slug is null;

create or replace function public.get_public_property(property_slug text) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'property',to_jsonb(p)-array['owner_id','created_at','updated_at'],
    'profile',jsonb_build_object('name',a.name,'email',a.email,'phone',a.phone,'agency',a.agency,'bio',a.bio,'avatar_url',a.avatar_url),
    'film',(select jsonb_build_object('src',v.video_url,'poster',coalesce(v.poster_url,p.images[1])) from public.property_video_jobs v join public.property_orders o on o.id=v.order_id where v.property_id=p.id and v.video_url is not null and public.property_order_fulfilled(o.id))
  ) from public.property_url_slugs u join public.properties p on p.id=u.property_id
    join public.profiles a on a.id=p.owner_id
    where u.slug=property_slug and p.status='published' limit 1;
$$;
revoke all on function public.get_public_property(text) from public;
grant execute on function public.get_public_property(text) to anon,authenticated;
create or replace function public.admin_publish_property(listing_id uuid,actor_id uuid,grant_reason text,
  expected_session text default null,expected_attempt integer default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare listing public.properties; purchase public.property_orders; done boolean; is_free boolean;
begin
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  if grant_reason is null or length(btrim(grant_reason))<1 or length(grant_reason)>500 then raise exception 'Add a reason for this publication'; end if;
  select * into listing from public.properties where id=listing_id for update;
  if not found then raise exception 'Property not available'; end if;
  insert into public.property_orders(property_id,owner_id) values(listing.id,listing.owner_id) on conflict(property_id) do nothing;
  select * into purchase from public.property_orders where property_id=listing.id for update;
  -- The server expires an existing open Stripe session before this transaction.
  -- Fence in-flight session creation by rotating the attempt under the same lock.
  if purchase.checkout_session_id is distinct from expected_session or
    (expected_attempt is not null and purchase.attempt<>expected_attempt) then
    raise exception 'Checkout changed. Refresh this property and try again' using errcode='P0409';
  end if;
  is_free:=purchase.status<>'paid';
  if is_free then
    insert into public.property_admin_grants(order_id,property_id,owner_id,granted_by,reason)
      values(purchase.id,listing.id,listing.owner_id,actor_id,btrim(grant_reason)) on conflict(order_id) do nothing;
  end if;
  update public.property_orders set attempt=attempt+1,publication_requested_at=now(),publication_completed_at=null,
    publication_error=null,video_status=case when video_status='delivered' then 'delivered' else 'pending' end
    where id=purchase.id;
  done:=public.finish_property_publication(purchase.id);
  if not done then raise exception 'Complete the property and agent contact details before publishing'; end if;
  insert into public.platform_admin_audit(actor_id,property_id,action,details)
    values(actor_id,listing.id,'publish',jsonb_build_object('complimentary',is_free,'reason',btrim(grant_reason),'title',listing.title));
  select * into listing from public.properties where id=listing_id;
  return jsonb_build_object('published',true,'complimentary',is_free,'paid',purchase.status='paid','publicPath',coalesce('/'||listing.address_slug,'/p/'||listing.slug));
end;
$$;
revoke all on function public.admin_publish_property(uuid,uuid,text,text,integer) from public,anon,authenticated;
grant execute on function public.admin_publish_property(uuid,uuid,text,text,integer) to service_role;
notify pgrst,'reload schema';


-- Extend the existing photo limit without changing ownership or publication checks.
alter table public.properties drop constraint if exists properties_images_check;
alter table public.properties add constraint properties_images_check check (cardinality(images) <= 40);
notify pgrst,'reload schema';


-- Read state is private to the listing owner; email jobs are server-only.
alter table public.inquiries add column if not exists read_at timestamptz;
create index if not exists inquiries_owner_unread on public.inquiries(owner_id) where read_at is null;

create or replace function public.mark_inquiries_read(inquiry_ids uuid[]) returns integer
language plpgsql security definer set search_path='' as $$
declare changed integer;
begin
  if auth.uid() is null or coalesce(cardinality(inquiry_ids),0) > 100 then return 0; end if;
  update public.inquiries set read_at=now()
    where owner_id=auth.uid() and id=any(inquiry_ids) and read_at is null;
  get diagnostics changed = row_count;
  return changed;
end;
$$;
revoke all on function public.mark_inquiries_read(uuid[]) from public,anon;
grant execute on function public.mark_inquiries_read(uuid[]) to authenticated;

create table if not exists public.lead_email_jobs (
  inquiry_id uuid primary key references public.inquiries(id) on delete cascade,
  recipient text not null,
  details jsonb not null,
  email_payload jsonb,
  status text not null default 'pending' check(status in ('pending','processing','sent','failed')),
  attempts integer not null default 0,
  available_at timestamptz not null default now(),
  first_attempt_at timestamptz,
  locked_until timestamptz,
  lease_token uuid,
  sent_at timestamptz,
  provider_id text,
  last_error text,
  created_at timestamptz not null default now()
);
alter table public.lead_email_jobs enable row level security;
revoke all on public.lead_email_jobs from public,anon,authenticated;
grant select,update on public.lead_email_jobs to service_role;
create index if not exists lead_email_jobs_due on public.lead_email_jobs(available_at) where status in ('pending','processing');

create or replace function public.enqueue_lead_email() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  insert into public.lead_email_jobs(inquiry_id,recipient,details)
  select new.id,coalesce(u.email,''),jsonb_build_object(
    'agentName',p.name,'propertyTitle',coalesce(l.title,'Property inquiry'),
    'name',new.name,'email',new.email,'phone',new.phone,'message',new.message)
  from auth.users u join public.profiles p on p.id=u.id
  left join public.properties l on l.id=new.property_id
  where u.id=new.owner_id
  on conflict(inquiry_id) do nothing;
  return new;
end;
$$;
revoke all on function public.enqueue_lead_email() from public,anon,authenticated;
drop trigger if exists inquiry_email_notification on public.inquiries;
create trigger inquiry_email_notification after insert on public.inquiries
for each row execute function public.enqueue_lead_email();

create or replace function public.claim_lead_emails(batch_size integer default 2)
returns setof public.lead_email_jobs
language plpgsql security definer set search_path='' as $$
begin
  -- Resend's idempotency keys expire after 24h. Never retry an uncertain send
  -- beyond 20h, even if a worker stopped after the provider accepted it.
  update public.lead_email_jobs set status='failed',last_error='retry_window_expired',lease_token=null,locked_until=null
    where status in ('pending','processing') and first_attempt_at < now()-interval '20 hours'
      and (locked_until is null or locked_until < now());
  return query
  with due as (
    select j.inquiry_id from public.lead_email_jobs j
    where ((j.status='pending' and j.available_at<=now())
      or (j.status='processing' and j.locked_until<now()))
      and j.attempts<8
    order by j.available_at,j.created_at for update skip locked
    limit greatest(1,least(coalesce(batch_size,2),5))
  )
  update public.lead_email_jobs j set status='processing',attempts=j.attempts+1,
    first_attempt_at=coalesce(j.first_attempt_at,now()),locked_until=now()+interval '2 minutes',lease_token=gen_random_uuid()
  from due where j.inquiry_id=due.inquiry_id returning j.*;
end;
$$;
revoke all on function public.claim_lead_emails(integer) from public,anon,authenticated;
grant execute on function public.claim_lead_emails(integer) to service_role;

create or replace function public.finish_lead_email(job_id uuid,job_lease uuid,delivered_id text default null,failure_code text default null,retryable boolean default true)
returns boolean language plpgsql security definer set search_path='' as $$
begin
  update public.lead_email_jobs set
    status=case when delivered_id is not null then 'sent' when retryable and attempts<8 then 'pending' else 'failed' end,
    sent_at=case when delivered_id is not null then now() else null end,
    provider_id=delivered_id,last_error=left(failure_code,80),
    available_at=now()+make_interval(secs=>least(3600,60*power(2,attempts-1))::integer),
    lease_token=null,locked_until=null
  where inquiry_id=job_id and lease_token=job_lease and status='processing' and locked_until>now();
  return found;
end;
$$;
revoke all on function public.finish_lead_email(uuid,uuid,text,text,boolean) from public,anon,authenticated;
grant execute on function public.finish_lead_email(uuid,uuid,text,text,boolean) to service_role;
notify pgrst,'reload schema';


-- Installs a protected manual recovery action; installation starts no jobs.
create or replace function public.admin_resume_byteplus_film(listing_id uuid,actor_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  perform 1 from public.properties where id=listing_id for update;
  if not found then raise exception 'Property unavailable' using errcode='P0409'; end if;
  select * into purchase from public.property_orders where property_id=listing_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then
    raise exception 'Publication access required' using errcode='P0409';
  end if;
  select * into job from public.property_video_jobs where order_id=purchase.id for update;
  if not found or job.status<>'failed' or job.provider_phase is distinct from 'provider_failed'
    or job.lease_until>now() or job.attempts>=3
    or job.model_config->'profile'->>'provider' is distinct from 'byteplus'
    or job.montage_plan is null or job.montage_next_shot>=jsonb_array_length(job.montage_plan->'shots') then
    raise exception 'This film cannot be resumed safely' using errcode='P0409';
  end if;
  -- Only a definitive POST rejection may release its reservation. Timeouts,
  -- accepted tasks, failed GETs and provider-completed failures must not re-POST.
  if coalesce(job.last_error,'') <> 'The video provider rejected this scene. Check API credentials, API credits and model settings. No new generation will be submitted automatically.'
    and coalesce(job.last_error,'') !~ '^BytePlus rejected scene [0-9]+ \(HTTP (400|401|402|403|404|422|429)[;)]' then
    raise exception 'Review the original provider request before retrying' using errcode='P0409';
  end if;
  select * into scene from public.property_film_scenes where order_id=job.order_id
    and generation=job.montage_generation and shot_index=job.montage_next_shot for update;
  if not found or scene.request_id is not null or scene.status is distinct from 'submitting'
    or scene.model_config->>'provider' is distinct from 'byteplus' then
    raise exception 'The existing scene request needs reconciliation' using errcode='P0409';
  end if;
  insert into public.platform_admin_audit(actor_id,property_id,action,details)
    values(actor_id,listing_id,'resume_byteplus_film',jsonb_build_object(
      'generation',job.montage_generation,'scene',job.montage_next_shot,
      'previous_error',job.last_error,'completed_scenes',job.montage_next_shot));
  delete from public.property_film_scenes where order_id=job.order_id
    and generation=job.montage_generation and shot_index=job.montage_next_shot;
  update public.property_video_jobs set status='processing',provider_phase='generating',
    attempts=attempts+1,montage_failures=0,last_error=null,lease_token=null,lease_until=null,
    next_poll_at=now(),updated_at=now() where order_id=job.order_id;
  return jsonb_build_object('videoStatus','processing','savedScenes',job.montage_next_shot);
end;
$$;
revoke all on function public.admin_resume_byteplus_film(uuid,uuid) from public,anon,authenticated;
grant execute on function public.admin_resume_byteplus_film(uuid,uuid) to service_role;


-- One-time Seedance 2.5 minimum-duration repair. Installation starts no jobs.
create or replace function public.admin_repair_byteplus_duration(listing_id uuid,actor_id uuid,p_rate numeric,p_max numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
  old_budget jsonb; new_budget jsonb; sources jsonb; total_seconds integer; total_cost numeric;
  rate numeric; max_usd numeric; cap numeric; total integer;
begin
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  if p_rate is null or not (p_rate>0 and p_rate<=100) or p_max is null or not (p_max>0 and p_max<=20) then
    raise exception 'Invalid budget configuration' using errcode='P0409'; end if;
  perform 1 from public.properties where id=listing_id for update;
  if not found then raise exception 'Property unavailable' using errcode='P0409'; end if;
  select * into purchase from public.property_orders where property_id=listing_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then
    raise exception 'Publication access required' using errcode='P0409'; end if;
  select * into job from public.property_video_jobs where order_id=purchase.id for update;
  if not found or job.status<>'failed' or job.provider_phase is distinct from 'provider_failed' or job.lease_until>now()
    or job.model_config->'profile'->>'provider' is distinct from 'byteplus'
    or job.model_config->'profile'->>'endpoint' is distinct from 'dreamina-seedance-2-5-260628'
    or job.model_config->'profile'->'input'->>'resolution' is distinct from '720p'
    or job.model_config->'profile'->'input'->>'generate_audio' is distinct from 'false'
    or job.montage_plan->>'timing' is distinct from 'variable-v1'
    or jsonb_typeof(job.montage_plan->'shots') is distinct from 'array'
    or job.montage_plan->'generationBudget'->>'version' is distinct from '2'
    or coalesce(job.last_error,'') !~ '^BytePlus rejected scene [0-9]+ \(HTTP 400; code InvalidParameter[^;]*; duration [23]s\)' then
    raise exception 'This film is not eligible for the duration repair' using errcode='P0409'; end if;
  old_budget:=job.montage_plan->'generationBudget';
  if old_budget->>'model' is distinct from 'dreamina-seedance-2-5-260628'
    or old_budget->>'resolution' is distinct from '720p'
    or old_budget->>'usdPerSecond' is null or not ((old_budget->>'usdPerSecond')::numeric>0 and (old_budget->>'usdPerSecond')::numeric<=100)
    or old_budget->>'maxUsd' is null or not ((old_budget->>'maxUsd')::numeric>0 and (old_budget->>'maxUsd')::numeric<=20) then
    raise exception 'Saved budget needs review' using errcode='P0409'; end if;
  total:=jsonb_array_length(job.montage_plan->'shots');
  if total<1 or total>23 or job.montage_next_shot>=total or exists(
    select 1 from jsonb_array_elements(job.montage_plan->'shots') s where coalesce(s->>'seconds','') !~ '^[2-5]$') then
    raise exception 'Invalid scene timeline' using errcode='P0409'; end if;
  select * into scene from public.property_film_scenes where order_id=job.order_id
    and generation=job.montage_generation and shot_index=job.montage_next_shot for update;
  if not found or scene.request_id is not null or scene.status is distinct from 'submitting'
    or scene.model_config->>'provider' is distinct from 'byteplus'
    or coalesce(scene.model_input->>'duration','') !~ '^[23]$' then
    raise exception 'The scene request needs reconciliation' using errcode='P0409'; end if;
  -- All previous scenes must already be saved, with exactly the generated length
  -- the corrected budget will count. Never erase a possibly accepted request.
  if (select count(*) from public.property_film_scenes s where s.order_id=job.order_id
      and s.generation=job.montage_generation and s.shot_index<job.montage_next_shot
      and s.status='completed' and s.request_id is not null
      and s.model_config->>'provider'='byteplus'
      and (s.model_input->>'duration')::integer=greatest(4,(job.montage_plan->'shots'->s.shot_index->>'seconds')::integer))<>job.montage_next_shot
    or exists(select 1 from public.property_film_scenes s where s.order_id=job.order_id
      and s.generation=job.montage_generation and s.shot_index>job.montage_next_shot) then
    raise exception 'Existing scenes need review' using errcode='P0409'; end if;
  rate:=greatest(p_rate,(old_budget->>'usdPerSecond')::numeric);
  max_usd:=least(p_max,(old_budget->>'maxUsd')::numeric);
  cap:=floor(max_usd*100*0.8)/100;
  select jsonb_agg(greatest(4,(s->>'seconds')::integer) order by n),
    sum(greatest(4,(s->>'seconds')::integer)),sum(ceil(rate*greatest(4,(s->>'seconds')::integer)*100))/100
    into sources,total_seconds,total_cost from jsonb_array_elements(job.montage_plan->'shots') with ordinality as x(s,n);
  if total_cost>cap then raise exception 'Corrected durations exceed the approved budget' using errcode='P0409'; end if;
  new_budget:=jsonb_build_object('version',3,'model',old_budget->>'model','resolution','720p',
    'sceneSeconds',sources,'generatedSeconds',total_seconds,'usdPerSecond',rate,'maxUsd',max_usd,
    'plannedScenes',total,'estimatedGenerationUsd',total_cost,'reserveUsd',max_usd-cap);
  insert into public.platform_admin_audit(actor_id,property_id,action,details) values(actor_id,listing_id,
    'repair_byteplus_duration',jsonb_build_object('generation',job.montage_generation,'previous_budget',old_budget,
    'corrected_budget',new_budget,'completed_scenes',job.montage_next_shot));
  delete from public.property_film_scenes where order_id=job.order_id and generation=job.montage_generation and shot_index=job.montage_next_shot;
  -- Source generation is corrected; photographs, final shot lengths, artifacts,
  -- model snapshot, music and generation ID remain unchanged.
  update public.property_video_jobs set montage_plan=jsonb_set(montage_plan,'{generationBudget}',new_budget),
    status='processing',provider_phase='generating',attempts=attempts+1,montage_failures=0,last_error=null,
    lease_token=null,lease_until=null,next_poll_at=now(),updated_at=now() where order_id=job.order_id;
  return jsonb_build_object('videoStatus','processing','savedScenes',job.montage_next_shot,'budget',new_budget);
end;
$$;
revoke all on function public.admin_repair_byteplus_duration(uuid,uuid,numeric,numeric) from public,anon,authenticated;
grant execute on function public.admin_repair_byteplus_duration(uuid,uuid,numeric,numeric) to service_role;


-- Overlap two BytePlus generations per film, while committing saved clips in order.
-- Completed films are never requeued. New workers remain sequential before this upgrade.
alter table public.property_video_jobs add column if not exists byteplus_parallel boolean not null default true;

create or replace function public.reserve_byteplus_lookahead(p_order uuid,p_lease uuid,p_attempt integer,p_index integer,p_input jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing'
    or job.lease_token is distinct from p_lease or job.attempts<>p_attempt or job.lease_until<=now()
    or not job.byteplus_parallel or job.model_config->'profile'->>'provider' is distinct from 'byteplus'
    or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1'
    or job.montage_plan->'generationBudget'->>'version' is distinct from '3'
    or p_index is null or p_index<>job.montage_next_shot+1 or p_index>=jsonb_array_length(job.montage_plan->'shots') then return null; end if;
  -- The previous POST must already have an accepted ID before overlapping work.
  if not exists(select 1 from public.property_film_scenes where order_id=p_order and generation=job.montage_generation
    and shot_index=job.montage_next_shot and status='submitted' and request_id is not null) then return null; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=job.montage_generation and shot_index=p_index for update;
  if found then
    if scene.request_id is null then
      update public.property_film_scenes set status='uncertain',updated_at=now() where order_id=p_order and generation=scene.generation and shot_index=p_index;
      update public.property_video_jobs set provider_phase='uncertain',lease_token=null,lease_until=null,
        last_error='The next scene submission needs reconciliation. No automatic resubmission.',updated_at=now() where order_id=p_order;
      return null;
    end if;
    return to_jsonb(scene)||jsonb_build_object('submit',false);
  end if;
  if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>128000
    or p_input->'duration' is distinct from job.montage_plan->'generationBudget'->'sceneSeconds'->p_index
    or p_input->>'resolution' is distinct from '720p' or p_input->>'generate_audio' is distinct from 'false'
    or p_input ? 'frames' then return null; end if;
  insert into public.property_film_scenes(order_id,generation,shot_index,status,model_config,model_input)
    values(p_order,job.montage_generation,p_index,'submitting',job.model_config->'profile',p_input) returning * into scene;
  return to_jsonb(scene)||jsonb_build_object('submit',true);
end;
$$;
revoke all on function public.reserve_byteplus_lookahead(uuid,uuid,integer,integer,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_byteplus_lookahead(uuid,uuid,integer,integer,jsonb) to service_role;

create or replace function public.bind_property_film_scene(p_order uuid,p_generation uuid,p_index integer,p_request text)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  if p_request !~ '^[a-zA-Z0-9_-]{1,160}$' then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing'
    or job.montage_generation is distinct from p_generation or (job.montage_next_shot<>p_index and not (job.byteplus_parallel and job.model_config->'profile'->>'provider'='byteplus' and p_index=job.montage_next_shot+1))
    or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1' then return false; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=p_generation and shot_index=p_index for update;
  if not found or scene.status not in ('submitting','submitted','uncertain') or (scene.request_id is not null and scene.request_id<>p_request) then return false; end if;
  update public.property_film_scenes set request_id=p_request,status='submitted',updated_at=now() where order_id=p_order and generation=p_generation and shot_index=p_index;
  update public.property_video_jobs set provider_phase='generating',last_error=null,next_poll_at=now(),updated_at=now() where order_id=p_order;
  return true;
end;
$$;
revoke all on function public.bind_property_film_scene(uuid,uuid,integer,text) from public,anon,authenticated;
grant execute on function public.bind_property_film_scene(uuid,uuid,integer,text) to service_role;

create or replace function public.checkpoint_property_ai_film(p_order uuid,p_lease uuid,p_attempt integer,
  p_plan jsonb default null,p_scene integer default null,p_edit integer default null,p_url text default null,
  p_error text default null,p_failure text default 'delayed')
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; total integer; known boolean;
begin
  if num_nonnulls(p_plan,p_scene,p_edit,p_url,p_error)>1 then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing' or job.lease_token is distinct from p_lease
    or job.attempts<>p_attempt or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1' then return false; end if;
  if p_error is not null then
    if job.byteplus_parallel and job.model_config->'profile'->>'provider'='byteplus' then
      select not exists(select 1 from public.property_film_scenes where order_id=p_order and generation=job.montage_generation
        and shot_index between job.montage_next_shot and job.montage_next_shot+1 and request_id is null
        and status in ('submitting','uncertain')) into known;
    else
      select exists(select 1 from public.property_film_scenes where order_id=p_order and generation=job.montage_generation and shot_index=job.montage_next_shot and request_id is not null) into known;
    end if;
    if p_failure='uncertain' and not known then
      update public.property_film_scenes set status='uncertain',updated_at=now() where order_id=p_order and generation=job.montage_generation and request_id is null
        and shot_index between job.montage_next_shot and job.montage_next_shot+case when job.byteplus_parallel and job.model_config->'profile'->>'provider'='byteplus' then 1 else 0 end;
    end if;
    update public.property_video_jobs set montage_failures=montage_failures+1,
      status=case when p_failure='failed' or (p_failure='delayed' and montage_failures>=2) then 'failed' else 'processing' end,
      provider_phase=case when p_failure='uncertain' and not known then 'uncertain' when p_failure='failed' then 'provider_failed' when p_failure='delayed' and montage_failures>=2 then 'failed' else 'generating' end,
      last_error=left(p_error,500),lease_token=null,lease_until=null,next_poll_at=now()+interval '2 minutes',updated_at=now() where order_id=p_order;
    return true;
  end if;
  if p_plan is not null then
    if job.montage_plan is not null or p_plan->>'engine' is distinct from 'higgsfield-montage-v1'
      or jsonb_typeof(p_plan->'shots') is distinct from 'array' or octet_length(p_plan::text)>128000 then return false; end if;
    total:=jsonb_array_length(p_plan->'shots');
    if total<1 or total>23 then return false; end if;
    update public.property_video_jobs set montage_plan=p_plan where order_id=p_order returning * into job;
  end if;
  total:=jsonb_array_length(job.montage_plan->'shots');
  if p_scene is not null then
    if total is null or p_scene<>job.montage_next_shot or p_scene>=total then return false; end if;
    update public.property_film_scenes set status='completed',updated_at=now()
      where order_id=p_order and generation=job.montage_generation and shot_index=p_scene and request_id is not null and status='submitted';
    if not found then return false; end if;
    update public.property_video_jobs set montage_next_shot=montage_next_shot+1 where order_id=p_order returning * into job;
  end if;
  if p_edit is not null then
    if total is null or job.montage_next_shot<>total or p_edit<>job.montage_edited_shots or p_edit>=total then return false; end if;
    update public.property_video_jobs set montage_edited_shots=montage_edited_shots+1 where order_id=p_order returning * into job;
  end if;
  if p_url is not null then
    if total is null or job.montage_next_shot<>total or job.montage_edited_shots<>total or p_url !~ '^https://' then return false; end if;
    update public.property_video_jobs set status='completed',provider_phase='completed',video_url=p_url,replacement_pending=false,
      poster_url=montage_plan->'shots'->0->>'image' where order_id=p_order;
    update public.property_orders set video_status='delivered' where id=p_order;
  end if;
  update public.property_video_jobs set montage_failures=0,last_error=null,lease_token=null,lease_until=null,
    next_poll_at=case when num_nonnulls(p_plan,p_scene,p_edit,p_url)>0 then now() else now()+interval '30 seconds' end,updated_at=now() where order_id=p_order;
  return true;
end;
$$;
revoke all on function public.checkpoint_property_ai_film(uuid,uuid,integer,jsonb,integer,integer,text,text,text) from public,anon,authenticated;
grant execute on function public.checkpoint_property_ai_film(uuid,uuid,integer,jsonb,integer,integer,text,text,text) to service_role;

create or replace function public.admin_resume_byteplus_film(listing_id uuid,actor_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes; rejected_index integer;
begin
  perform 1 from public.platform_admins where user_id=actor_id for share;
  if not found then raise exception 'Administrator access required' using errcode='42501'; end if;
  perform 1 from public.properties where id=listing_id for update;
  if not found then raise exception 'Property unavailable' using errcode='P0409'; end if;
  select * into purchase from public.property_orders where property_id=listing_id for update;
  if not found or not public.property_order_fulfilled(purchase.id) then
    raise exception 'Publication access required' using errcode='P0409';
  end if;
  select * into job from public.property_video_jobs where order_id=purchase.id for update;
  if not found or job.status<>'failed' or job.provider_phase is distinct from 'provider_failed'
    or job.lease_until>now() or job.attempts>=3
    or job.model_config->'profile'->>'provider' is distinct from 'byteplus'
    or job.montage_plan is null or job.montage_next_shot>=jsonb_array_length(job.montage_plan->'shots') then
    raise exception 'This film cannot be resumed safely' using errcode='P0409';
  end if;
  -- Only a definitive POST rejection may release its reservation. Timeouts,
  -- accepted tasks, failed GETs and provider-completed failures must not re-POST.
  if coalesce(job.last_error,'') <> 'The video provider rejected this scene. Check API credentials, API credits and model settings. No new generation will be submitted automatically.'
    and coalesce(job.last_error,'') !~ '^BytePlus rejected scene [0-9]+ \(HTTP (400|401|402|403|404|422|429)[;)]' then
    raise exception 'Review the original provider request before retrying' using errcode='P0409';
  end if;
  rejected_index:=coalesce(substring(job.last_error from '^BytePlus rejected scene ([0-9]+) ')::integer-1,job.montage_next_shot);
  if rejected_index<>job.montage_next_shot and not (job.byteplus_parallel and rejected_index=job.montage_next_shot+1) then
    raise exception 'The rejected scene needs review' using errcode='P0409'; end if;
  select * into scene from public.property_film_scenes where order_id=job.order_id
    and generation=job.montage_generation and shot_index=rejected_index for update;
  if not found or scene.request_id is not null or scene.status is distinct from 'submitting'
    or scene.model_config->>'provider' is distinct from 'byteplus' then
    raise exception 'The existing scene request needs reconciliation' using errcode='P0409';
  end if;
  insert into public.platform_admin_audit(actor_id,property_id,action,details)
    values(actor_id,listing_id,'resume_byteplus_film',jsonb_build_object(
      'generation',job.montage_generation,'scene',rejected_index,
      'previous_error',job.last_error,'completed_scenes',job.montage_next_shot));
  delete from public.property_film_scenes where order_id=job.order_id
    and generation=job.montage_generation and shot_index=rejected_index;
  update public.property_video_jobs set status='processing',provider_phase='generating',
    byteplus_parallel=case when job.last_error ~ '^BytePlus rejected scene [0-9]+ \(HTTP 429[;)]' then false else byteplus_parallel end,
    attempts=attempts+1,montage_failures=0,last_error=null,lease_token=null,lease_until=null,
    next_poll_at=now(),updated_at=now() where order_id=job.order_id;
  return jsonb_build_object('videoStatus','processing','savedScenes',job.montage_next_shot);
end;
$$;
revoke all on function public.admin_resume_byteplus_film(uuid,uuid) from public,anon,authenticated;
grant execute on function public.admin_resume_byteplus_film(uuid,uuid) to service_role;


-- One shared BytePlus capacity pool, independent of property/job deletion.
-- Three is the published Individual limit; raise only after BytePlus confirms the account quota.
create table if not exists public.byteplus_queue_settings (
  id boolean primary key default true check(id),
  max_active integer not null default 3 check(max_active between 1 and 10),
  cooldown_until timestamptz not null default '-infinity'
);
insert into public.byteplus_queue_settings(id) values(true) on conflict do nothing;
alter table public.byteplus_queue_settings enable row level security;
revoke all on public.byteplus_queue_settings from public,anon,authenticated,service_role;
grant select on public.byteplus_queue_settings to service_role;

alter table public.property_video_jobs add column if not exists byteplus_last_dispatch timestamptz not null default '-infinity';
alter table public.property_video_jobs add column if not exists byteplus_rate_limits integer not null default 0;
create table if not exists public.byteplus_scene_slots (
  order_id uuid not null,
  generation uuid not null,
  shot_index integer not null,
  request_id text unique,
  active boolean not null default true,
  next_check_at timestamptz not null default now(),
  primary key(order_id,generation,shot_index)
);
alter table public.byteplus_scene_slots enable row level security;
revoke all on public.byteplus_scene_slots from public,anon,authenticated,service_role;
grant select on public.byteplus_scene_slots to service_role;
create index if not exists byteplus_active_slots on public.byteplus_scene_slots(next_check_at) where active;
-- Preserve existing accepted and ambiguous requests. Never free unknown submissions by time alone.
insert into public.byteplus_scene_slots(order_id,generation,shot_index,request_id,active)
  select order_id,generation,shot_index,request_id,status in ('submitting','submitted','uncertain')
  from public.property_film_scenes where model_config->>'provider'='byteplus'
  on conflict do nothing;

create or replace function public.guard_byteplus_scene_capacity() returns trigger
language plpgsql security definer set search_path='' as $$
declare settings public.byteplus_queue_settings; job public.property_video_jobs; own_active boolean;
begin
  if new.model_config->>'provider' is distinct from 'byteplus' then return new; end if;
  if new.status in ('completed','failed') then return new; end if;
  -- The singleton lock serializes reservations across Vercel instances, not just within one film.
  select * into settings from public.byteplus_queue_settings where id=true for update;
  if not found or settings.cooldown_until>now() then return null; end if;
  if (select count(*) from public.byteplus_scene_slots where active)>=settings.max_active then return null; end if;
  if exists(select 1 from public.byteplus_scene_slots where order_id=new.order_id and generation=new.generation
    and shot_index=new.shot_index and (active or request_id is not null)) then return null; end if;
  select * into job from public.property_video_jobs where order_id=new.order_id;
  select exists(select 1 from public.byteplus_scene_slots where order_id=new.order_id and active) into own_active;
  -- Give a ready film with no active scene a turn before a second scene of another film.
  -- Among films without a slot, the least recently served film goes first.
  if exists(select 1 from public.property_video_jobs j
    where j.order_id<>new.order_id and j.status='processing' and j.provider_phase not in ('uncertain','provider_failed')
      and j.model_config->'profile'->>'provider'='byteplus' and j.montage_plan is not null
      and j.montage_next_shot<jsonb_array_length(j.montage_plan->'shots') and j.next_poll_at<=now()
      and public.property_order_fulfilled(j.order_id)
      and not exists(select 1 from public.property_film_scenes f where f.order_id=j.order_id and f.generation=j.montage_generation and f.shot_index=j.montage_next_shot)
      and not exists(select 1 from public.byteplus_scene_slots s where s.order_id=j.order_id and s.active)
      and (own_active or (j.byteplus_last_dispatch,j.created_at,j.order_id)<(job.byteplus_last_dispatch,job.created_at,job.order_id))
  ) then return null; end if;
  insert into public.byteplus_scene_slots(order_id,generation,shot_index)
    values(new.order_id,new.generation,new.shot_index)
    on conflict(order_id,generation,shot_index) do update set active=true,request_id=null,next_check_at=now();
  update public.property_video_jobs set byteplus_last_dispatch=clock_timestamp() where order_id=new.order_id;
  return new;
end;
$$;
revoke all on function public.guard_byteplus_scene_capacity() from public,anon,authenticated,service_role;
drop trigger if exists byteplus_capacity_before_scene on public.property_film_scenes;
create trigger byteplus_capacity_before_scene before insert on public.property_film_scenes
  for each row execute function public.guard_byteplus_scene_capacity();

create or replace function public.sync_byteplus_scene_slot() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.model_config->>'provider'='byteplus' then
    update public.byteplus_scene_slots set request_id=coalesce(new.request_id,request_id),
      active=case when new.status in ('completed','failed') then false else active end
      where order_id=new.order_id and generation=new.generation and shot_index=new.shot_index
        and (request_id is null or request_id=new.request_id);
  end if;
  return new;
end;
$$;
revoke all on function public.sync_byteplus_scene_slot() from public,anon,authenticated,service_role;
drop trigger if exists byteplus_slot_after_scene on public.property_film_scenes;
create trigger byteplus_slot_after_scene after insert or update on public.property_film_scenes
  for each row execute function public.sync_byteplus_scene_slot();


-- Keep prior recovery/duration-repair installers compatible with the shared pool.
-- Deleting a property or an unknown submission does NOT free an in-flight slot.
create or replace function public.release_rejected_byteplus_slot() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if old.model_config->>'provider'='byteplus' and old.request_id is null and old.status='submitting'
    and exists(select 1 from public.property_video_jobs j where j.order_id=old.order_id
      and j.montage_generation=old.generation and j.status='failed' and j.provider_phase='provider_failed'
      and ((j.last_error ~ '^BytePlus rejected scene [0-9]+ \(HTTP (400|401|402|403|404|422|429)[;)]'
        and substring(j.last_error from '^BytePlus rejected scene ([0-9]+) ')::integer=old.shot_index+1)
        or (j.last_error='The video provider rejected this scene. Check API credentials, API credits and model settings. No new generation will be submitted automatically.'
          and j.montage_next_shot=old.shot_index))) then
    update public.byteplus_scene_slots set active=false where order_id=old.order_id and generation=old.generation
      and shot_index=old.shot_index and request_id is null;
  end if;
  return old;
end;
$$;
revoke all on function public.release_rejected_byteplus_slot() from public,anon,authenticated,service_role;
drop trigger if exists byteplus_rejected_slot_before_delete on public.property_film_scenes;
create trigger byteplus_rejected_slot_before_delete before delete on public.property_film_scenes
  for each row execute function public.release_rejected_byteplus_slot();

-- A short polling lease prevents simultaneous wakeups from all checking the same provider task.
create or replace function public.claim_byteplus_slot_checks() returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
  with due as (select order_id,generation,shot_index from public.byteplus_scene_slots
    where active and request_id is not null and next_check_at<=now()
    order by next_check_at limit 10 for update skip locked), claimed as (
    update public.byteplus_scene_slots s set next_check_at=now()+interval '30 seconds' from due d
      where (s.order_id,s.generation,s.shot_index)=(d.order_id,d.generation,d.shot_index)
      returning s.request_id
  ) select coalesce(jsonb_agg(claimed),'[]'::jsonb) into result from claimed;
  return result;
end;
$$;
revoke all on function public.claim_byteplus_slot_checks() from public,anon,authenticated;
grant execute on function public.claim_byteplus_slot_checks() to service_role;
create or replace function public.finish_byteplus_scene_slot(p_request text) returns boolean
language plpgsql security definer set search_path='' as $$
begin
  update public.byteplus_scene_slots set active=false where request_id=p_request and active;
  return found;
end;
$$;
revoke all on function public.finish_byteplus_scene_slot(text) from public,anon,authenticated;
grant execute on function public.finish_byteplus_scene_slot(text) to service_role;

-- Only an explicit rejected POST can release an unbound slot. 429 is deferred, not a failed film.
create or replace function public.reject_byteplus_scene(p_order uuid,p_lease uuid,p_attempt integer,p_generation uuid,p_index integer,p_http integer)
returns boolean language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes; delay_seconds integer;
begin
  if p_http is null or p_http not in (400,401,402,403,404,422,429) then return false; end if;
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return false; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or job.status<>'processing' or job.lease_token is distinct from p_lease or job.attempts<>p_attempt
    or job.montage_generation is distinct from p_generation or job.model_config->'profile'->>'provider' is distinct from 'byteplus'
    or not public.property_order_fulfilled(p_order) then return false; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=p_generation and shot_index=p_index for update;
  if not found or scene.status<>'submitting' or scene.request_id is not null then return false; end if;
  update public.byteplus_scene_slots set active=false
    where order_id=p_order and generation=p_generation and shot_index=p_index and request_id is null;
  if p_http<>429 or job.byteplus_rate_limits>=5 then return false; end if;
  delay_seconds:=least(480,60*(2^job.byteplus_rate_limits)::integer);
  update public.byteplus_queue_settings set cooldown_until=greatest(cooldown_until,now()+make_interval(secs=>delay_seconds)) where id=true;
  delete from public.property_film_scenes where order_id=p_order and generation=p_generation and shot_index=p_index;
  update public.property_video_jobs set provider_phase='generating',byteplus_rate_limits=byteplus_rate_limits+1,
    lease_token=null,lease_until=null,last_error=null,next_poll_at=now()+make_interval(secs=>delay_seconds),updated_at=now() where order_id=p_order;
  return true;
end;
$$;
revoke all on function public.reject_byteplus_scene(uuid,uuid,integer,uuid,integer,integer) from public,anon,authenticated;
grant execute on function public.reject_byteplus_scene(uuid,uuid,integer,uuid,integer,integer) to service_role;

create or replace function public.reserve_property_film_scene(p_order uuid,p_lease uuid,p_attempt integer,p_input jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing' or job.lease_token is distinct from p_lease
    or job.lease_until<=now() or job.attempts<>p_attempt or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1'
    or job.montage_plan is null or job.montage_next_shot>=jsonb_array_length(job.montage_plan->'shots') then return null; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=job.montage_generation and shot_index=job.montage_next_shot for update;
  if found then
    if scene.request_id is null then
      update public.property_film_scenes set status='uncertain',updated_at=now() where order_id=p_order and generation=scene.generation and shot_index=scene.shot_index;
      update public.property_video_jobs set provider_phase='uncertain',lease_token=null,lease_until=null,
        last_error='A scene submission needs reconciliation. No additional generation will be submitted automatically.',updated_at=now() where order_id=p_order;
      return null;
    end if;
    return to_jsonb(scene)||jsonb_build_object('submit',false);
  end if;
  if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>128000 then return null; end if;
  insert into public.property_film_scenes(order_id,generation,shot_index,status,model_config,model_input)
    values(p_order,job.montage_generation,job.montage_next_shot,'submitting',job.model_config->'profile',p_input) returning * into scene;
  if not found then return null; end if;
  update public.property_video_jobs set provider_phase='submitting',updated_at=now() where order_id=p_order;
  return to_jsonb(scene)||jsonb_build_object('submit',true);
end;
$$;
revoke all on function public.reserve_property_film_scene(uuid,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_property_film_scene(uuid,uuid,integer,jsonb) to service_role;


create or replace function public.reserve_byteplus_lookahead(p_order uuid,p_lease uuid,p_attempt integer,p_index integer,p_input jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare purchase public.property_orders; job public.property_video_jobs; scene public.property_film_scenes;
begin
  select * into purchase from public.property_orders where id=p_order;
  if not found or purchase.property_id is null then return null; end if;
  perform 1 from public.properties where id=purchase.property_id for update;
  select * into purchase from public.property_orders where id=p_order for update;
  select * into job from public.property_video_jobs where order_id=p_order for update;
  if not found or not public.property_order_fulfilled(p_order) or job.status<>'processing'
    or job.lease_token is distinct from p_lease or job.attempts<>p_attempt or job.lease_until<=now()
    or not job.byteplus_parallel or job.model_config->'profile'->>'provider' is distinct from 'byteplus'
    or job.model_config->>'engine' is distinct from 'higgsfield-montage-v1'
    or job.montage_plan->'generationBudget'->>'version' is distinct from '3'
    or p_index is null or p_index<>job.montage_next_shot+1 or p_index>=jsonb_array_length(job.montage_plan->'shots') then return null; end if;
  -- The previous POST must already have an accepted ID before overlapping work.
  if not exists(select 1 from public.property_film_scenes where order_id=p_order and generation=job.montage_generation
    and shot_index=job.montage_next_shot and status='submitted' and request_id is not null) then return null; end if;
  select * into scene from public.property_film_scenes where order_id=p_order and generation=job.montage_generation and shot_index=p_index for update;
  if found then
    if scene.request_id is null then
      update public.property_film_scenes set status='uncertain',updated_at=now() where order_id=p_order and generation=scene.generation and shot_index=p_index;
      update public.property_video_jobs set provider_phase='uncertain',lease_token=null,lease_until=null,
        last_error='The next scene submission needs reconciliation. No automatic resubmission.',updated_at=now() where order_id=p_order;
      return null;
    end if;
    return to_jsonb(scene)||jsonb_build_object('submit',false);
  end if;
  if jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>128000
    or p_input->'duration' is distinct from job.montage_plan->'generationBudget'->'sceneSeconds'->p_index
    or p_input->>'resolution' is distinct from '720p' or p_input->>'generate_audio' is distinct from 'false'
    or p_input ? 'frames' then return null; end if;
  insert into public.property_film_scenes(order_id,generation,shot_index,status,model_config,model_input)
    values(p_order,job.montage_generation,p_index,'submitting',job.model_config->'profile',p_input) returning * into scene;
  if not found then return null; end if;
  return to_jsonb(scene)||jsonb_build_object('submit',true);
end;
$$;
revoke all on function public.reserve_byteplus_lookahead(uuid,uuid,integer,integer,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_byteplus_lookahead(uuid,uuid,integer,integer,jsonb) to service_role;


notify pgrst,'reload schema';


-- Durable deletion/retention jobs. Storage bytes are removed through Storage API,
-- never by deleting storage.objects rows. Existing drafts receive 14 days' grace.
alter table public.profiles add column if not exists profile_completed_at timestamptz;
update public.profiles set profile_completed_at=now() where profile_completed_at is null
  and length(btrim(name))>=2 and email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  and length(regexp_replace(phone,'[^0-9]','','g'))>=8;
alter table public.properties add column if not exists first_published_at timestamptz;
alter table public.properties add column if not exists draft_expires_at timestamptz default (now()+interval '14 days');
update public.properties p set first_published_at=coalesce(p.first_published_at,now()),draft_expires_at=null
where p.status='published' or exists(select 1 from public.property_orders o where o.property_id=p.id and o.publication_completed_at is not null)
  or exists(select 1 from public.property_legacy_access a where a.property_id=p.id);

create table if not exists public.account_cleanup_jobs (
  id uuid primary key default gen_random_uuid(),
  kind text not null check(kind in ('property','account')),
  target_id uuid not null,
  owner_id uuid not null,
  paths jsonb not null,
  status text not null default 'pending' check(status in ('pending','completed')),
  next_attempt_at timestamptz not null default (now()+interval '10 minutes'),
  lease_token uuid, lease_until timestamptz,
  attempts integer not null default 0,
  last_error text,
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  unique(kind,target_id)
);
create table if not exists public.account_lifecycle_audit (
  id bigint generated always as identity primary key,
  actor_id uuid, target_id uuid not null, action text not null,
  created_at timestamptz not null default now()
);
alter table public.account_cleanup_jobs enable row level security;
alter table public.account_lifecycle_audit enable row level security;
revoke all on public.account_cleanup_jobs,public.account_lifecycle_audit from public,anon,authenticated,service_role;
grant select on public.account_cleanup_jobs,public.account_lifecycle_audit to service_role;

create or replace function public.account_accepts_uploads() returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles where id=auth.uid()) and not exists(
   select 1 from public.account_cleanup_jobs where kind='account' and owner_id=auth.uid());
$$;
revoke all on function public.account_accepts_uploads() from public,anon;
grant execute on function public.account_accepts_uploads() to authenticated;
drop policy if exists "Deleted accounts cannot upload" on storage.objects;
create policy "Deleted accounts cannot upload" on storage.objects as restrictive for insert to authenticated
with check (public.account_accepts_uploads());
drop policy if exists "Deleted accounts cannot update storage" on storage.objects;
create policy "Deleted accounts cannot update storage" on storage.objects as restrictive for update to authenticated
using (public.account_accepts_uploads()) with check(public.account_accepts_uploads());

create or replace function public.track_profile_completion() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 new.profile_completed_at:=case when tg_op='UPDATE' then old.profile_completed_at else null end;
 if new.profile_completed_at is null and length(btrim(new.name))>=2
   and new.email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
   and length(regexp_replace(new.phone,'[^0-9]','','g'))>=8 then new.profile_completed_at:=now(); end if;
 return new;
end; $$;
drop trigger if exists track_profile_completion on public.profiles;
create trigger track_profile_completion before insert or update on public.profiles for each row execute function public.track_profile_completion();

create or replace function public.guard_property_lifecycle() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 -- Lock the owner row to serialize account deletion against listing creation.
 perform 1 from public.profiles where id=new.owner_id for update;
 if exists(select 1 from public.account_cleanup_jobs where kind='account' and owner_id=new.owner_id) then
   raise exception 'This account is being deleted';
 end if;
 if tg_op='INSERT' then
   if exists(select 1 from public.account_cleanup_jobs where kind='property' and target_id=new.id) then raise exception 'This property has been deleted'; end if;
   new.first_published_at:=null; new.draft_expires_at:=now()+interval '14 days';
 else
   new.first_published_at:=old.first_published_at; new.draft_expires_at:=old.draft_expires_at;
 end if;
 if new.status='published' then new.first_published_at:=coalesce(new.first_published_at,now()); new.draft_expires_at:=null; end if;
 return new;
end; $$;
drop trigger if exists guard_property_lifecycle on public.properties;
create trigger guard_property_lifecycle before insert or update on public.properties for each row execute function public.guard_property_lifecycle();

create or replace function public.queue_deleted_property_storage() returns trigger
language plpgsql security definer set search_path='' as $$
declare paths jsonb; purchase record;
begin
 paths:=jsonb_build_array(jsonb_build_object('bucket','property-images','prefix',old.owner_id::text||'/'||old.id::text));
 for purchase in select id from public.property_orders where property_id=old.id loop
   paths:=paths || jsonb_build_array(
     jsonb_build_object('bucket','property-videos','prefix',old.owner_id::text||'/'||purchase.id::text),
     jsonb_build_object('bucket','property-video-work','prefix',old.owner_id::text||'/'||purchase.id::text));
   delete from public.property_film_scenes where order_id=purchase.id;
 end loop;
 insert into public.account_cleanup_jobs(kind,target_id,owner_id,paths) values('property',old.id,old.owner_id,paths) on conflict(kind,target_id) do nothing;
 return old;
end; $$;
drop trigger if exists queue_deleted_property_storage on public.properties;
create trigger queue_deleted_property_storage before delete on public.properties for each row execute function public.queue_deleted_property_storage();

create or replace function public.admin_delete_property(p_target uuid,p_actor uuid) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.platform_admins where user_id=p_actor) then raise exception 'Administrator access required'; end if;
 perform 1 from public.properties where id=p_target for update;
 if exists(select 1 from public.property_orders where property_id=p_target and status='pending' and expires_at>now() and not public.property_order_fulfilled(id)) then
   raise exception using errcode='P0409',message='A checkout is still active. Try again after it expires or the payment is confirmed.';
 end if;
 delete from public.properties where id=p_target;
 if not found then return false; end if;
 insert into public.account_lifecycle_audit(actor_id,target_id,action) values(p_actor,p_target,'delete_property');
 return true;
end; $$;
create or replace function public.admin_delete_account(p_target uuid,p_actor uuid) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.platform_admins where user_id=p_actor) then raise exception 'Administrator access required'; end if;
 if p_target=p_actor or exists(select 1 from public.platform_admins where user_id=p_target) then raise exception 'Administrator accounts cannot be deleted here'; end if;
 perform 1 from public.profiles where id=p_target for update;
 if not found then return false; end if;
 perform 1 from public.properties where owner_id=p_target order by id for update;
 if exists(select 1 from public.property_orders where owner_id=p_target and property_id is not null and status='pending' and expires_at>now() and not public.property_order_fulfilled(id)) then
   raise exception using errcode='P0409',message='A checkout is still active. Try again after it expires or the payment is confirmed.';
 end if;
 insert into public.account_cleanup_jobs(kind,target_id,owner_id,paths) values('account',p_target,p_target,
   jsonb_build_array(
     jsonb_build_object('bucket','property-images','prefix',p_target::text),
     jsonb_build_object('bucket','property-videos','prefix',p_target::text),
     jsonb_build_object('bucket','property-video-work','prefix',p_target::text),
     jsonb_build_object('bucket','agent-avatars','prefix',p_target::text))) on conflict(kind,target_id) do nothing;
 delete from public.properties where owner_id=p_target;
 insert into public.account_lifecycle_audit(actor_id,target_id,action) values(p_actor,p_target,'delete_account_requested');
 return true;
end; $$;

create or replace function public.expire_unpublished_properties() returns integer
language plpgsql security definer set search_path='' as $$
declare listing record; removed integer:=0;
begin
 for listing in select p.id from public.properties p where p.status='draft' and p.first_published_at is null
   and p.draft_expires_at<=now() and not public.property_has_live_access(p.id,p.owner_id)
   and not exists(select 1 from public.property_orders o where o.property_id=p.id and
     (o.paid_at is not null or o.status<>'pending' or o.expires_at>now()))
   order by p.draft_expires_at limit 100 for update of p skip locked loop
   -- Recheck payment state after locking the property, with a fresh snapshot.
   if exists(select 1 from public.properties p where p.id=listing.id and public.property_has_live_access(p.id,p.owner_id))
     or exists(select 1 from public.property_orders o where o.property_id=listing.id and (o.paid_at is not null or o.status<>'pending' or o.expires_at>now())) then continue; end if;
   delete from public.properties where id=listing.id;
   insert into public.account_lifecycle_audit(target_id,action) values(listing.id,'expire_unpublished_draft');
   removed:=removed+1;
 end loop;
 return removed;
end; $$;

create or replace function public.claim_account_cleanup(p_lease uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare job public.account_cleanup_jobs;
begin
 select * into job from public.account_cleanup_jobs where status='pending' and next_attempt_at<=now()
   and (lease_until is null or lease_until<now()) order by next_attempt_at,id limit 1 for update skip locked;
 if not found then return null; end if;
 update public.account_cleanup_jobs set lease_token=p_lease,lease_until=now()+interval '3 minutes',attempts=attempts+1
   where id=job.id returning * into job;
 return to_jsonb(job);
end; $$;
create or replace function public.finish_account_cleanup(p_id uuid,p_lease uuid,p_done boolean,p_failed boolean default false) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 update public.account_cleanup_jobs set status=case when p_done then 'completed' else 'pending' end,
   completed_at=case when p_done then now() else null end,
   next_attempt_at=now()+case when p_failed then interval '15 minutes' else interval '1 minute' end,
   last_error=case when p_failed then 'Storage or authentication cleanup needs retry.' else null end,
   lease_until=null,lease_token=null where id=p_id and lease_token=p_lease and status='pending';
 return found;
end; $$;

revoke all on function public.track_profile_completion(),public.guard_property_lifecycle(),public.queue_deleted_property_storage(),
 public.admin_delete_property(uuid,uuid),public.admin_delete_account(uuid,uuid),public.expire_unpublished_properties(),
 public.claim_account_cleanup(uuid),public.finish_account_cleanup(uuid,uuid,boolean,boolean) from public,anon,authenticated;
grant execute on function public.admin_delete_property(uuid,uuid),public.admin_delete_account(uuid,uuid),public.expire_unpublished_properties(),
 public.claim_account_cleanup(uuid),public.finish_account_cleanup(uuid,uuid,boolean,boolean) to service_role;
